-- ----------------------------
-- Table structure for agent_run
-- ----------------------------
DROP TABLE IF EXISTS `agent_run`;
CREATE TABLE `agent_run`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `run_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行编号',
  `task_id` int NULL DEFAULT NULL COMMENT '所属匹配任务ID',
  `user_id` int NULL DEFAULT NULL COMMENT '触发这次运行的用户ID',
  `run_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '运行类型',
  `run_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '运行中' COMMENT '运行状态',
  `current_round` int NOT NULL DEFAULT 0 COMMENT '当前已调度轮次',
  `total_round` int NOT NULL DEFAULT 0 COMMENT '实际用掉的调度轮次',
  `input_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '入参快照',
  `output_summary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '收尾原因与最终结论',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `cost_millis` int NULL DEFAULT NULL COMMENT '耗时',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_agent_run_no`(`run_no` ASC) USING BTREE,
  INDEX `idx_agent_run_task`(`task_id` ASC) USING BTREE,
  INDEX `idx_agent_run_status`(`run_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 64 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Agent运行记录表' ROW_FORMAT = DYNAMIC;

