-- Records of agent_run
-- ----------------------------

-- ----------------------------
-- Table structure for agent_step
-- ----------------------------
DROP TABLE IF EXISTS `agent_step`;
CREATE TABLE `agent_step`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `run_id` int NOT NULL COMMENT '所属运行记录ID',
  `round_no` int NOT NULL DEFAULT 0 COMMENT '第几轮调度',
  `step_index` int NOT NULL DEFAULT 0 COMMENT '本轮内的第几步',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '这一步是哪个角色在做',
  `step_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '步骤类型',
  `step_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '步骤名称',
  `tool_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工具编码',
  `request_params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '入参',
  `response_result` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '返回内容',
  `step_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '已完成' COMMENT '步骤状态',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `cost_millis` int NULL DEFAULT NULL COMMENT '耗时',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_agent_step_run`(`run_id` ASC) USING BTREE,
  INDEX `idx_agent_step_run_round`(`run_id` ASC, `round_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 366 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Agent步骤记录表' ROW_FORMAT = DYNAMIC;

