-- ----------------------------
-- Table structure for tool_call_log
-- ----------------------------
DROP TABLE IF EXISTS `tool_call_log`;
CREATE TABLE `tool_call_log`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `run_id` int NOT NULL COMMENT '所属运行记录ID',
  `agent_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发起调用的Agent角色编码',
  `tool_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工具编码',
  `request_params` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '调用入参',
  `response_result` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '返回内容',
  `row_count` int NULL DEFAULT NULL COMMENT '返回行数',
  `success` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '是' COMMENT '是否成功',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '失败原因',
  `cost_millis` int NULL DEFAULT NULL COMMENT '耗时',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tool_call_log_run`(`run_id` ASC) USING BTREE,
  INDEX `idx_tool_call_log_tool`(`tool_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 312 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '工具调用日志表' ROW_FORMAT = DYNAMIC;

