INSERT INTO `agent_step` VALUES (356, 63, 3, 3, 'AUDITOR', '工具调用', '调用工具 read_candidate_preference', 'read_candidate_preference', '{\"candidate_member_id\": 687}', '{\"candidate_member_id\": 687, \"nickname\": \"泽墨\", \"gender\": \"男\", \"age\": 30, \"rent_budget\": 3200, \"tidiness\": \"整洁\", \"occupation\": \"银行柜员\", \"lease_term\": \"1-2年\", \"store\": \"紫竹店\", \"area\": \"闵行\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"做银行柜员的，公司离紫竹店不远。作息很规律，一般十点半前睡，早上六点多就起了。比较爱干净，公共区域用完马上收拾。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢养猫、背包客、爬山、看综艺。工作稳定，计划在这边住一到两年。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。\", \"interest_tags\": [\"养猫\", \"背包客\", \"爬山\", \"看综艺\", \"咖啡\"], \"preference\": {\"age\": {\"range\": [24, 34], \"required\": \"必须\"}, \"budget\": {\"range\": [2000, 4200], \"required\": \"必须\"}, \"tidiness\": {\"min\": \"整洁\", \"required\": \"必须\"}, \"store\": {\"scope\": \"不限\", \"required\": \"加分\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": null, \"required\": \"加分\"}, \"pet\": {\"accept\": \"无所谓\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', '已完成', NULL, '2026-10-06 22:59:16', '2026-10-06 22:59:16', 8, '2026-10-06 22:59:17');
INSERT INTO `agent_step` VALUES (357, 63, 3, 4, 'AUDITOR', '工具调用', '调用工具 save_audit_result', 'save_audit_result', '{\"candidate_member_id\": 687, \"audit_status\": \"通过\"}', '{\"candidate_member_id\": 687, \"audit_status\": \"通过\", \"reject_code\": null, \"returned\": 1}', '已完成', NULL, '2026-10-06 22:59:17', '2026-10-06 22:59:17', 6, '2026-10-06 22:59:18');
INSERT INTO `agent_step` VALUES (358, 63, 3, 5, 'AUDITOR', '工具调用', '调用工具 read_candidate_preference', 'read_candidate_preference', '{\"candidate_member_id\": 627}', '{\"candidate_member_id\": 627, \"nickname\": \"钧轩\", \"gender\": \"男\", \"age\": 23, \"rent_budget\": 3300, \"tidiness\": \"整洁\", \"occupation\": \"公务员\", \"lease_term\": \"1-2年\", \"store\": \"七宝店\", \"area\": \"闵行\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"经常\", \"self_intro\": \"我在闵行这边上班，做公务员。作息很规律，一般十点半前睡，早上六点多就起了。比较爱干净，公共区域用完马上收拾。有抽烟的习惯，会尽量去阳台或楼下抽。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢听音乐会、羽毛球、科幻、端游。工作稳定，计划在这边住一到两年。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。相处简单一点，有事好商量。\", \"interest_tags\": [\"听音乐会\", \"羽毛球\", \"科幻\", \"端游\", \"养猫\", \"手游\"], \"preference\": {\"age\": {\"range\": [19, 27], \"required\": \"加分\"}, \"budget\": {\"range\": [2500, 4800], \"required\": \"必须\"}, \"tidiness\": {\"min\": null, \"required\": \"加分\"}, \"store\": {\"scope\": \"不限\", \"required\": \"加分\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": null, \"required\": \"加分\"}, \"pet\": {\"accept\": \"接受\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', '已完成', NULL, '2026-10-06 22:59:18', '2026-10-06 22:59:18', 8, '2026-10-06 22:59:18');
INSERT INTO `agent_step` VALUES (359, 63, 3, 6, 'AUDITOR', '工具调用', '调用工具 save_audit_result', 'save_audit_result', '{\"candidate_member_id\": 627, \"audit_status\": \"通过\"}', '{\"candidate_member_id\": 627, \"audit_status\": \"通过\", \"reject_code\": null, \"returned\": 1}', '已完成', NULL, '2026-10-06 22:59:19', '2026-10-06 22:59:19', 10, '2026-10-06 22:59:19');
INSERT INTO `agent_step` VALUES (360, 63, 3, 7, 'AUDITOR', '工具调用', '调用工具 read_candidate_preference', 'read_candidate_preference', '{\"candidate_member_id\": 619}', '{\"candidate_member_id\": 619, \"nickname\": \"阳云\", \"gender\": \"男\", \"age\": 27, \"rent_budget\": 3300, \"tidiness\": \"整洁\", \"occupation\": \"花店店主\", \"lease_term\": \"3个月以下\", \"store\": \"七宝店\", \"area\": \"闵行\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"目前在闵行做花店店主，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。比较爱干净，公共区域用完马上收拾。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢传记、房车旅行、看纪录片。最近是过渡期，先住两三个月看看。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。如果能偶尔一起做饭就更好了。\", \"interest_tags\": [\"传记\", \"房车旅行\", \"看纪录片\"], \"preference\": {\"age\": {\"range\": [24, 30], \"required\": \"加分\"}, \"budget\": {\"range\": [2300, 3800], \"required\": \"必须\"}, \"tidiness\": {\"min\": \"整洁\", \"required\": \"加分\"}, \"store\": {\"scope\": \"同片区\", \"required\": \"必须\"}, \"schedule\": {\"accept\": [\"早睡早起\"], \"required\": \"必须\"}, \"lease\": {\"min\": null, \"required\": \"加分\"}, \"pet\": {\"accept\": \"不接受\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', '已完成', NULL, '2026-10-06 22:59:20', '2026-10-06 22:59:20', 9, '2026-10-06 22:59:20');
INSERT INTO `agent_step` VALUES (361, 63, 3, 8, 'AUDITOR', '工具调用', '调用工具 save_audit_result', 'save_audit_result', '{\"candidate_member_id\": 619, \"audit_status\": \"否决\", \"reject_code\": \"MISMATCH_HARD\", \"reject_reason\": \"候选方必须项要求同片区门店，申请方意向张江店（浦东）与候选方七宝店（闵行）不同片区，硬性不满足。\"}', '{\"candidate_member_id\": 619, \"audit_status\": \"否决\", \"reject_code\": \"MISMATCH_HARD\", \"returned\": 1}', '已完成', NULL, '2026-10-06 22:59:21', '2026-10-06 22:59:21', 10, '2026-10-06 22:59:21');
INSERT INTO `agent_step` VALUES (362, 63, 3, 9, 'AUDITOR', '工具调用', '调用工具 read_candidate_preference', 'read_candidate_preference', '{\"candidate_member_id\": 599}', '{\"candidate_member_id\": 599, \"nickname\": \"松航\", \"gender\": \"男\", \"age\": 25, \"rent_budget\": 2800, \"tidiness\": \"整洁\", \"occupation\": \"理财顾问\", \"lease_term\": \"6-12个月\", \"store\": \"七宝店\", \"area\": \"闵行\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"我在闵行这边上班，做理财顾问。每天七点前起床晨跑，晚上很少熬夜。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看纪录片、爬山、看综艺、背包客。打算先签一年以内。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。\", \"interest_tags\": [\"看纪录片\", \"爬山\", \"看综艺\", \"背包客\"], \"preference\": {\"age\": {\"range\": [20, 30], \"required\": \"加分\"}, \"budget\": {\"range\": [2300, 3800], \"required\": \"加分\"}, \"tidiness\": {\"min\": \"整洁\", \"required\": \"加分\"}, \"store\": {\"scope\": \"同片区\", \"required\": \"必须\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": null, \"required\": \"加分\"}, \"pet\": {\"accept\": \"无所谓\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', '已完成', NULL, '2026-10-06 22:59:21', '2026-10-06 22:59:21', 7, '2026-10-06 22:59:22');
INSERT INTO `agent_step` VALUES (363, 63, 3, 10, 'AUDITOR', '工具调用', '调用工具 save_audit_result', 'save_audit_result', '{\"candidate_member_id\": 599, \"audit_status\": \"否决\", \"reject_code\": \"MISMATCH_HARD\", \"reject_reason\": \"候选方必须项要求同片区门店，申请方意向张江店（浦东）与候选方七宝店（闵行）不同片区，硬性不满足。\"}', '{\"candidate_member_id\": 599, \"audit_status\": \"否决\", \"reject_code\": \"MISMATCH_HARD\", \"returned\": 1}', '已完成', NULL, '2026-10-06 22:59:23', '2026-10-06 22:59:23', 9, '2026-10-06 22:59:23');
INSERT INTO `agent_step` VALUES (364, 63, 3, 11, 'AUDITOR', '角色结论', '审核官结论', NULL, '{\"tool_calls\": 10, \"rounds\": 11}', '\"模型给出结论 5 条，其中通过 3 人、否决 2 人\"', '已完成', NULL, '2026-10-06 22:59:24', '2026-10-06 22:59:24', 0, '2026-10-06 22:59:25');
INSERT INTO `agent_step` VALUES (365, 63, 4, 1, 'SUPERVISOR', '调度', '第 4 轮调度', NULL, '\"【任务】\\n为租客 #1（男，27 岁，张江店，早睡早起）匹配，要求交付 8 人\\n\\n【当前候选统计】\\n累计候选 15 人 / 已通过 8 人 / 已否决 7 人 / 待审核 0 人\\n距离交付要求还差 0 人\\n否决分类：PREFERENCE_CONFLICT 3 人（双方合住习惯直接冲突）、MISMATCH_HARD 4 人（申请方不满足候选方标为必须的条件）\\n\\n【本次画像】\\n本次已经补了 1 版，最新一版是 v2（这一版重点补：为租客 #1（男，27岁，张江店，早睡早起）生成或补全画像，重点明确作息、门店、性别等硬性匹配维度，便于筛选官精准检索。）\\n【审核官点名的缺失维度】还没有点名过\\n\\n【你可以派的角色】\\nPORTRAIT 画像师 —— 可调工具：读租客档案、读租客动态、读兴趣标签词表\\nSCREENER 筛选官 —— 可调工具：读申请方合住偏好、按条件检索候选租客、写候选池\\nAUDITOR 审核官 —— 可调工具：读候选方偏好与画像、回填审核结论\\nFINISH 收尾 —— 结束本次匹配，把已经通过审核的候选交给租客\\n\\n【已经发生的事】\\n第 1 轮 画像师：模型给出：性格 4 个、生活方式 6 个、合住需求 5 个标签\\n第 2 轮 筛选官：模型给出候选 15 个，放宽说明「放宽门店加分项1级（同片区→不限）」\\n第 3 轮 审核官：模型给出结论 5 条，其中通过 3 人、否决 2 人\\n第 3 轮 审核官：模型给出结论 0 条，其中通过 0 人、否决 0 人\\n\\n【已用调度轮次】4 / 上限 12\\n【筛选官已放宽次数】1 / 上限 3\"', '{\"next_agent\": \"FINISH\", \"instruction\": \"将已通过审核的 8 人候选池交付给租客 #1，完成本次匹配\", \"reason\": \"已通过 8 人，达到交付要求 8 人，待审核 0 人，且调度轮次已用 4/12，符合收尾条件\"}', '已完成', NULL, '2026-10-06 22:59:25', '2026-10-06 22:59:25', 0, '2026-10-06 22:59:26');
INSERT INTO `ai_model_config` VALUES (1, '调度决策模型', 'DeepSeek', 'https://api.deepseek.com/v1', NULL, 'deepseek-chat', 0.00, 2048, '调度', '是', '主管的决策模型，要求输出稳定的结构化 JSON，温度固定为 0', '2026-10-03 20:00:00', '2026-10-06 23:49:15');
INSERT INTO `ai_model_config` VALUES (2, '画像提取模型', 'DeepSeek', 'https://api.deepseek.com/v1', NULL, 'deepseek-chat', 0.30, 2048, '画像', '是', '画像师提取标签与原文依据，允许少量措辞变化', '2026-10-03 20:00:00', '2026-10-06 23:49:15');
INSERT INTO `ai_model_config` VALUES (3, '候选筛选模型', 'DeepSeek', 'https://api.deepseek.com/v1', NULL, 'deepseek-chat', 0.00, 2048, '筛选', '是', '筛选官决定放宽哪个维度，要求结果可复现', '2026-10-03 20:00:00', '2026-10-06 23:49:15');
INSERT INTO `ai_model_config` VALUES (4, '双向审核模型', 'DeepSeek', 'https://api.deepseek.com/v1', NULL, 'deepseek-chat', 0.00, 1024, '审核', '是', '审核官逐人判定，温度固定为 0', '2026-10-03 20:00:00', '2026-10-06 23:49:15');
INSERT INTO `function_tool` VALUES (1, 'read_member_detail', '读租客档案', '读取当前租客的完整档案。提取画像前必须最先调用一次，一次运行里不要重复调用。参数 member_id 传租客ID，不传则默认读当前任务的租客。', '{\"type\": \"object\", \"properties\": {\"member_id\": {\"type\": \"integer\", \"description\": \"租客ID\"}}, \"required\": []}', '画像', 1, '是', 1, '2026-10-03 20:00:00', '2026-10-03 20:00:00');
INSERT INTO `function_tool` VALUES (2, 'read_member_moments', '读租客动态', '读取租客的动态原文，按发布时间倒序返回，单次最多 20 条。提取生活方式和合住需求标签前调用；档案里已经有足够依据时不要重复调用。', '{\"type\": \"object\", \"properties\": {\"member_id\": {\"type\": \"integer\", \"description\": \"租客ID\"}, \"limit\": {\"type\": \"integer\", \"description\": \"最多返回几条，1 到 20，默认 20\", \"minimum\": 1, \"maximum\": 20}}, \"required\": []}', '画像', 20, '是', 2, '2026-10-03 20:00:00', '2026-10-03 20:00:00');
INSERT INTO `function_tool` VALUES (3, 'list_interest_tags', '读兴趣标签词表', '读取兴趣标签词表，返回全部启用标签及其类目。给租客打兴趣标签前调用一次，打标签只能用词表里的词，不许自造。打标签之外的场合不要调用它。', '{\"type\": \"object\", \"properties\": {\"category\": {\"type\": \"string\", \"description\": \"标签类目，取值：运动、影音、美食、旅行、宠物、阅读、游戏、艺术，不传返回全部\"}}, \"required\": []}', '画像', NULL, '是', 3, '2026-10-03 20:00:00', '2026-10-03 21:11:54');
INSERT INTO `function_tool` VALUES (4, 'read_roommate_preference', '读申请方合住偏好', '读取申请方的合住偏好以及每个维度的必须或加分标注。筛选开始前必须最先调用一次。不用传租客编号，读的就是这次运行的发起人。标为必须的维度任何情况下都不许放宽。', '{\"type\": \"object\", \"properties\": {}, \"required\": []}', '筛选', 1, '是', 4, '2026-10-03 20:00:00', '2026-10-03 20:00:00');
INSERT INTO `function_tool` VALUES (5, 'search_members', '按条件检索候选租客', '按条件检索候选租客，只返回档案已通过审核且不是申请方本人的租客，单次最多返回 30 条，结果里带 total、returned、hasMore 三个数字。硬筛先调一次；不要用它穷举翻页，候选不够应当通过放宽加分项来解决。未提供的条件表示不限制。', '{\"type\": \"object\", \"properties\": {\"gender\": {\"type\": \"string\", \"description\": \"性别：男、女。合租只找同性，传申请方自己的性别\"}, \"age_min\": {\"type\": \"integer\", \"description\": \"年龄下限，18 到 80\"}, \"age_max\": {\"type\": \"integer\", \"description\": \"年龄上限，18 到 80\"}, \"budget_min\": {\"type\": \"integer\", \"description\": \"月租预算下限（元），800 到 20000\"}, \"budget_max\": {\"type\": \"integer\", \"description\": \"月租预算上限（元），800 到 20000\"}, \"tidiness_min\": {\"type\": \"string\", \"description\": \"最低整洁度：随意、一般、整洁、洁癖\"}, \"store_scope\": {\"type\": \"string\", \"description\": \"门店范围：同门店、同片区、不限\"}, \"store_id\": {\"type\": \"integer\", \"description\": \"申请方的意向门店编码，1 到 20，门店范围不是不限时必传\"}, \"schedule_accept\": {\"type\": \"string\", \"description\": \"可接受的作息，多选用逗号分隔：早睡早起、正常作息、夜猫子\"}, \"lease_min\": {\"type\": \"string\", \"description\": \"最短租期：3个月以下、3-6个月、6-12个月、1-2年、2年以上\"}, \"interest_tags\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"兴趣标签，取值必须来自兴趣标签词表\"}}, \"required\": []}', '筛选', 30, '是', 5, '2026-10-03 20:00:00', '2026-10-03 20:00:00');
INSERT INTO `function_tool` VALUES (6, 'save_candidates', '写候选池', '把本轮筛出的候选一次性写入候选池，必须带上是第几轮筛出来的；放宽了条件时必须填 relax_note 写清放宽了什么。代码会校验只能放宽标为加分的维度、每一轮只放宽一个维度、放宽幅度不越界，越界直接拒绝并把原因返回。本轮没筛到候选时也要调用一次，把放宽说明或结论带回来。', '{\"type\": \"object\", \"properties\": {\"candidates\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"properties\": {\"candidate_member_id\": {\"type\": \"integer\", \"description\": \"候选租客ID\"}, \"screen_score\": {\"type\": \"integer\", \"description\": \"初筛得分，0 到 100\"}}, \"required\": [\"candidate_member_id\"]}, \"description\": \"候选列表，可以为空数组\"}, \"found_round\": {\"type\": \"integer\", \"description\": \"第几轮筛出来的，从 1 开始\"}, \"relax_note\": {\"type\": \"string\", \"description\": \"本轮放宽了什么，例如预算上限加 200，没放宽填空字符串\"}}, \"required\": [\"candidates\", \"found_round\"]}', '筛选', NULL, '是', 6, '2026-10-03 20:00:00', '2026-10-03 20:00:00');
INSERT INTO `function_tool` VALUES (7, 'read_candidate_preference', '读候选方偏好与画像', '读取某个候选租客的合住偏好与最新画像。审核一个候选前调用一次，一次只传一个候选ID，这是站在候选方立场反向评估的依据。已经审过的候选不要再重复调用。', '{\"type\": \"object\", \"properties\": {\"candidate_member_id\": {\"type\": \"integer\", \"description\": \"候选租客ID\"}}, \"required\": [\"candidate_member_id\"]}', '审核', 1, '是', 7, '2026-10-03 20:00:00', '2026-10-03 20:00:00');
INSERT INTO `function_tool` VALUES (8, 'save_audit_result', '回填审核结论', '把一个候选的审核结论回填到候选池，一次一条。否决时 reject_code 必须是 MISMATCH_HARD、PREFERENCE_CONFLICT、PORTRAIT_INSUFFICIENT 三个之一；填 PORTRAIT_INSUFFICIENT 时必须在 reject_reason 里说清缺哪个维度。审核通过也要调用它把通过状态写回去。', '{\"type\": \"object\", \"properties\": {\"candidate_member_id\": {\"type\": \"integer\", \"description\": \"候选租客ID\"}, \"audit_status\": {\"type\": \"string\", \"description\": \"审核结论：通过、否决\"}, \"reject_code\": {\"type\": \"string\", \"description\": \"否决原因分类，三选一：MISMATCH_HARD、PREFERENCE_CONFLICT、PORTRAIT_INSUFFICIENT\"}, \"reject_reason\": {\"type\": \"string\", \"description\": \"否决理由，判 PORTRAIT_INSUFFICIENT 时必须说明缺哪个维度\"}}, \"required\": [\"candidate_member_id\", \"audit_status\"]}', '审核', NULL, '是', 8, '2026-10-03 20:00:00', '2026-10-03 20:00:00');
