INSERT INTO `match_candidate` VALUES (50, 40, 40, 1, 95, '作息+1级', '否决', 'PREFERENCE_CONFLICT', '候选尹文昭经常吸烟，而申请方清和虽偶尔吸烟但要求室友不在屋里抽烟，且候选要求租期1-2年（必须）而申请方仅计划6-12个月，吸烟习惯与租期均冲突。', 3, '2026-10-04 12:48:36', '2026-10-04 12:48:46');
INSERT INTO `match_candidate` VALUES (51, 40, 117, 2, 88, '门店+1级', '否决', 'MISMATCH_HARD', '候选舟朗要求租期至少3-6个月（必须）满足，但门店为唐镇店而申请方意向张江店，且候选要求室友不在屋里抽烟，申请方偶尔吸烟，硬性门店与吸烟偏好不符。', 3, '2026-10-04 12:48:37', '2026-10-04 12:48:46');
INSERT INTO `match_candidate` VALUES (52, 40, 66, 2, 85, '门店+1级', '否决', 'MISMATCH_HARD', '候选涵轩要求同片区门店（必须），其门店为金桥店而申请方意向张江店，硬性门店要求不满足。', 3, '2026-10-04 12:48:37', '2026-10-04 12:48:46');
INSERT INTO `match_candidate` VALUES (53, 40, 63, 2, 85, '门店+1级', '通过', NULL, NULL, 3, '2026-10-04 12:48:37', '2026-10-04 12:48:46');
INSERT INTO `match_candidate` VALUES (54, 40, 177, 2, 78, '门店+1级', '否决', 'MISMATCH_HARD', '候选谦砚要求预算1500-3000元（必须），申请方预算3500元超出上限，硬性预算不满足。', 3, '2026-10-04 12:48:37', '2026-10-04 12:48:46');
INSERT INTO `match_candidate` VALUES (55, 40, 58, 2, 75, '门店+1级', '否决', 'MISMATCH_HARD', '候选志言要求同门店（必须），其门店为金桥店而申请方意向张江店，硬性门店要求不满足。', 3, '2026-10-04 12:48:37', '2026-10-04 12:48:46');
INSERT INTO `match_candidate` VALUES (56, 40, 140, 2, 70, '门店+1级', '否决', 'PREFERENCE_CONFLICT', '候选夏松泽为夜猫子且经常吸烟、养宠，与申请方早睡早起、要求23点后安静及不在屋里抽烟的习惯直接冲突。', 3, '2026-10-04 12:48:37', '2026-10-04 12:48:46');
INSERT INTO `match_candidate` VALUES (57, 40, 875, 3, 82, '门店+1级', '否决', 'MISMATCH_HARD', '候选宇家要求租期至少3-6个月（必须）满足，但门店为中山北路店（普陀）而申请方意向张江店（浦东），跨区通勤不符。', 3, '2026-10-04 12:48:38', '2026-10-04 12:48:46');
