INSERT INTO `match_candidate` VALUES (59, 40, 846, 3, 80, '门店+1级', '否决', 'MISMATCH_HARD', '候选文泽要求同片区门店（必须），其门店为桃浦店（普陀）而申请方意向张江店（浦东），硬性门店要求不满足。', 3, '2026-10-04 12:48:38', '2026-10-04 12:48:46');
