INSERT INTO `match_candidate` VALUES (63, 40, 619, 3, 76, '门店+1级', '否决', 'MISMATCH_HARD', '候选方必须项「门店同片区」不满足：他要求七宝店（闵行）同片区，而申请方意向张江店（浦东），跨片区通勤不便。', 3, '2026-10-04 12:48:38', '2026-10-04 12:48:55');
INSERT INTO `match_candidate` VALUES (64, 40, 599, 3, 76, '门店+1级', '否决', 'MISMATCH_HARD', '候选方必须项「门店同片区」不满足：他要求七宝店（闵行）同片区，而申请方意向张江店（浦东），跨片区通勤不便。', 3, '2026-10-04 12:48:38', '2026-10-04 12:48:57');
