INSERT INTO `member_profile` VALUES (68, 69, '树锐', '男', '1991-10-22 00:00:00', 2900, '一般', '西点师', '1-2年', 2, '正常作息', '无', '不吸烟', '做西点师的，平时喜欢摄影、品酒，人比较好相处。', '卫生方面大家互相体谅就好。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '摄影,品酒,心理学', NULL, '已通过', NULL, '2026-10-01 20:24:00', '是', '2026-10-01 20:08:32', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (69, 70, '文泽', '男', '1985-03-26 00:00:00', 3500, '洁癖', '算法工程师', '6-12个月', 2, '正常作息', '有', '不吸烟', '我在浦东这边上班，做算法工程师。工作日朝九晚六，晚上偶尔追剧到十二点左右。有点洁癖，卫生间和厨房希望每次用完都擦干。养了一只猫，很安静，猫砂每天清。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢散文、传记、探店、乒乓球。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望室友能接受我养的小宠物。如果能偶尔一起做饭就更好了。', '散文,传记,探店,乒乓球,跑步,篮球', NULL, '已通过', NULL, '2026-10-03 13:57:48', '是', '2026-10-03 13:35:43', '2026-10-03 21:10:17');
