INSERT INTO `member_profile` VALUES (72, 73, '彤景', '女', '1993-08-06 00:00:00', 5300, '洁癖', '后端工程师', '1-2年', 2, '夜猫子', '无', '不吸烟', '目前在浦东做后端工程师，想找个近一点的地方住。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢密室逃脱、烘焙、剧本杀、下厨。工作稳定，计划在这边住一到两年。', '我睡得晚，希望室友对作息不要太敏感。相处简单一点，有事好商量。', '密室逃脱,烘焙,剧本杀,下厨,出境游,自驾游', NULL, '已通过', NULL, '2026-10-01 03:58:23', '否', '2026-10-01 03:54:21', '2026-10-03 21:10:17');
