INSERT INTO `member_profile` VALUES (79, 80, '昱言', '男', '1983-10-09 00:00:00', 4100, '随意', '产品经理', '6-12个月', 2, '夜猫子', '无', '不吸烟', '目前在浦东做产品经理，想找个近一点的地方住。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。对整洁要求不高，东西放得有点随意，不过不会影响别人。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢羽毛球、棋类、卡牌、健身。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。如果能偶尔一起做饭就更好了。', '羽毛球,棋类,卡牌,健身,露营', NULL, '已通过', NULL, '2026-10-03 04:18:26', '是', '2026-10-03 04:10:49', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (80, 81, '陶洲舟', '男', '2000-08-03 00:00:00', 3200, '一般', '心理咨询师', '1-2年', 2, '正常作息', '无', '不吸烟', '目前在浦东做心理咨询师，想找个近一点的地方住。一般十二点前睡觉，周末会稍微睡个懒觉。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢烘焙、茶道、追剧。工作稳定，计划在这边住一到两年。', '卫生方面大家互相体谅就好。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '烘焙,茶道,追剧', NULL, '已通过', NULL, '2026-10-03 17:21:10', '是', '2026-10-03 16:53:04', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (81, 82, '书楠', '女', '1998-03-15 00:00:00', 3900, '一般', '测绘工程师', '1-2年', 2, '正常作息', '无', '偶尔', '做测绘工程师的，公司离金桥店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。公共区域愿意排值日轮流打扫。偶尔会抽烟，但只在楼下抽，不在屋里。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢爬宠、滑雪、养鸟、品酒。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。能互相尊重彼此的空间就好。', '爬宠,滑雪,养鸟,品酒,游泳,咖啡', NULL, '已通过', NULL, '2026-10-03 09:57:47', '是', '2026-10-03 09:49:07', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (82, 83, '岚薇', '女', '1996-11-16 00:00:00', 3100, '一般', '品牌策划', '3-6个月', 2, '正常作息', '无', '不吸烟', '做品牌策划的，平时喜欢绘画、诗集，人比较好相处。', '卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '绘画,诗集,健身,插画,烧烤,电竞', NULL, '已通过', NULL, '2026-10-01 21:45:15', '是', '2026-10-01 21:29:39', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (83, 84, '筱嘉', '女', '1996-01-10 00:00:00', 5000, '整洁', '市场专员', '6-12个月', 2, '正常作息', '无', '不吸烟', '做市场专员的，公司离金桥店不远。一般十二点前睡觉，周末会稍微睡个懒觉。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢心理学、海岛游、瑜伽。打算先签一年以内。', '对动物毛发过敏，不能接受室友养宠物。如果能偶尔一起做饭就更好了。', '心理学,海岛游,瑜伽', NULL, '已通过', NULL, '2026-10-01 00:22:33', '是', '2026-10-01 00:06:52', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (84, 85, '禾书', '女', '1995-06-26 00:00:00', 4600, '洁癖', '瑜伽教练', '1-2年', 2, '早睡早起', '无', '不吸烟', '做瑜伽教练的，平时喜欢端游、骑行，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '端游,骑行,书法,出境游,经济学', NULL, '已通过', NULL, '2026-10-02 09:40:14', '是', '2026-10-02 09:24:18', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (85, 86, '之涵', '女', '1986-10-30 00:00:00', 1800, '随意', '测试工程师', '3个月以下', 2, '早睡早起', '无', '不吸烟', '目前在浦东做测试工程师，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。对整洁要求不高，东西放得有点随意，不过不会影响别人。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢跑步、滑雪、探店、撸狗。最近是过渡期，先住两三个月看看。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。如果能偶尔一起做饭就更好了。', '跑步,滑雪,探店,撸狗,追剧,房车旅行', NULL, '已通过', NULL, '2026-10-03 04:18:25', '是', '2026-10-03 04:10:55', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (86, 87, '洛心', '女', '1986-05-15 00:00:00', 3900, '随意', '采购专员', '3-6个月', 2, '早睡早起', '无', '不吸烟', '目前在浦东做采购专员，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。自己房间不算特别整齐，但公共区域用完会收拾。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢桌游、听音乐、追剧、唱歌。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。如果能偶尔一起做饭就更好了。', '桌游,听音乐,追剧,唱歌,养鱼,乐器', NULL, '已通过', NULL, '2026-10-02 09:21:15', '是', '2026-10-02 09:01:12', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (87, 88, '柏阳', '男', '1988-04-19 00:00:00', 3500, '洁癖', '记者', '6-12个月', 2, '正常作息', '无', '经常', '目前在浦东做记者，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。有点洁癖，卫生间和厨房希望每次用完都擦干。有抽烟的习惯，会尽量去阳台或楼下抽。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢拼图、舞蹈、背包客。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。能互相尊重彼此的空间就好。', '拼图,舞蹈,背包客', NULL, '已通过', NULL, '2026-10-03 07:32:29', '是', '2026-10-03 07:04:26', '2026-10-03 21:10:17');
