INSERT INTO `member_profile` VALUES (96, 97, '越林', '男', '1981-06-09 00:00:00', 4000, '一般', '记者', '1-2年', 3, '夜猫子', '无', '不吸烟', '目前在浦东做记者，想找个近一点的地方住。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢宠物公益、咖啡、主机游戏、品酒。工作稳定，计划在这边住一到两年。', '我睡得晚，希望室友对作息不要太敏感。相处简单一点，有事好商量。', '宠物公益,咖啡,主机游戏,品酒,看话剧', NULL, '已通过', NULL, '2026-10-01 03:41:12', '是', '2026-10-01 03:18:32', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (97, 98, '慕清', '女', '1996-04-12 00:00:00', 3000, '整洁', '后端工程师', '6-12个月', 3, '夜猫子', '有', '不吸烟', '我在浦东这边上班，做后端工程师。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。东西习惯分类收纳，厨房用完当天就擦干净。养了一只小狗，打过疫苗，每天早晚各遛一次。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢看展、杂志、养猫。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望室友能接受我养的小宠物。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '看展,杂志,养猫', NULL, '已通过', NULL, '2026-10-01 02:06:09', '是', '2026-10-01 01:38:07', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (98, 99, '彤筱', '女', '2001-08-23 00:00:00', 2300, '一般', '民警', '1-2年', 3, '早睡早起', '无', '偶尔', '目前在浦东做民警，想找个近一点的地方住。作息很规律，一般十点半前睡，早上六点多就起了。公共区域愿意排值日轮流打扫。偶尔会抽烟，但只在楼下抽，不在屋里。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢电竞、科幻、剧本杀。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。相处简单一点，有事好商量。', '电竞,科幻,剧本杀', NULL, '已通过', NULL, '2026-10-02 16:23:55', '是', '2026-10-02 16:06:21', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (99, 100, '雨筱', '女', '1989-02-25 00:00:00', 2100, '一般', '个体经营', '6-12个月', 3, '夜猫子', '有', '不吸烟', '我在浦东这边上班，做个体经营。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。卫生习惯一般，垃圾每天倒，房间一周收拾一次。养了一只猫，很安静，猫砂每天清。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢散文、听音乐、看电影、乒乓球。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望室友能接受我养的小宠物。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '散文,听音乐,看电影,乒乓球,看话剧', NULL, '已通过', NULL, '2026-10-01 00:33:51', '是', '2026-10-01 00:16:19', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (100, 101, '吕慕清', '女', '1995-07-10 00:00:00', 3000, '随意', '花店店主', '1-2年', 3, '早睡早起', '无', '不吸烟', '做花店店主的，公司离唐镇店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。自己房间不算特别整齐，但公共区域用完会收拾。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢端游、桌游、经济学、诗集。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '端游,桌游,经济学,诗集,看展,书法', NULL, '已通过', NULL, '2026-10-03 12:11:09', '是', '2026-10-03 11:48:23', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (101, 102, '之月', '女', '1997-05-20 00:00:00', 2700, '随意', '品牌策划', '6-12个月', 3, '早睡早起', '无', '偶尔', '目前在浦东做品牌策划，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。自己房间不算特别整齐，但公共区域用完会收拾。偶尔会抽烟，但只在楼下抽，不在屋里。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢乒乓球、手工、羽毛球。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '乒乓球,手工,羽毛球', NULL, '已通过', NULL, '2026-10-01 22:35:29', '是', '2026-10-01 22:30:48', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (102, 103, '安怡', '女', '1998-11-07 00:00:00', 2600, '一般', '财务经理', '6-12个月', 3, '早睡早起', '无', '不吸烟', '做财务经理的，平时喜欢羽毛球、听音乐，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '羽毛球,听音乐,看展,茶道,咖啡', NULL, '已通过', NULL, '2026-10-03 10:42:34', '是', '2026-10-03 10:16:44', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (103, 104, '瑾彤', '女', '1991-11-15 00:00:00', 2600, '随意', '测绘工程师', '3个月以下', 3, '正常作息', '无', '不吸烟', '做测绘工程师的，公司离唐镇店不远。一般十二点前睡觉，周末会稍微睡个懒觉。自己房间不算特别整齐，但公共区域用完会收拾。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢宠物公益、乐器、听播客、哲学。最近是过渡期，先住两三个月看看。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '宠物公益,乐器,听播客,哲学,游泳,城市漫步', NULL, '已通过', NULL, '2026-10-03 10:18:36', '是', '2026-10-03 10:04:17', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (104, 105, '亦墨', '男', '1985-08-09 00:00:00', 4200, '整洁', '审计师', '1-2年', 3, '正常作息', '有', '偶尔', '我在浦东这边上班，做审计师。作息算正常，十二点左右睡，早上八点前起。比较爱干净，公共区域用完马上收拾。养了一只猫，很安静，猫砂每天清。偶尔会抽烟，但只在楼下抽，不在屋里。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢养鸟、听播客、绘画。工作稳定，计划在这边住一到两年。', '希望室友爱干净，公共区域用完能及时收拾。希望室友能接受我养的小宠物。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '养鸟,听播客,绘画', NULL, '已通过', NULL, '2026-10-01 13:32:12', '是', '2026-10-01 13:18:28', '2026-10-03 21:10:17');
