INSERT INTO `member_profile` VALUES (117, 118, '舟朗', '男', '1997-04-05 00:00:00', 3800, '整洁', '事业单位职员', '1-2年', 3, '早睡早起', '无', '不吸烟', '目前在浦东做事业单位职员，想找个近一点的地方住。我习惯早睡早起，晚上十一点之后基本就不出声了。比较爱干净，公共区域用完马上收拾。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢陶艺、乐器、城市漫步、拼图。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '陶艺,乐器,城市漫步,拼图,密室逃脱', NULL, '已通过', NULL, '2026-10-01 22:40:55', '是', '2026-10-01 22:16:59', '2026-10-03 21:10:17');
