INSERT INTO `member_profile` VALUES (196, 197, '柏家', '男', '1984-08-14 00:00:00', 3400, '一般', '医生', '1-2年', 5, '正常作息', '无', '不吸烟', '做医生的，公司离漕河泾店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢舞蹈、日料、养鱼、瑜伽。工作稳定，计划在这边住一到两年。', '对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '舞蹈,日料,养鱼,瑜伽,绘画,听播客', NULL, '已通过', NULL, '2026-10-03 09:20:25', '是', '2026-10-03 09:17:57', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (197, 198, '舟时', '男', '2003-06-04 00:00:00', 3200, '整洁', '事业单位职员', '6-12个月', 5, '夜猫子', '无', '不吸烟', '目前在徐汇做事业单位职员，想找个近一点的地方住。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢摄影、背包客、绘画、乐器。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '摄影,背包客,绘画,乐器,桌游', NULL, '已通过', NULL, '2026-10-01 04:04:56', '是', '2026-10-01 04:00:55', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (198, 199, '楠楚', '女', '1998-07-05 00:00:00', 4800, '一般', '保险经纪人', '2年以上', 5, '正常作息', '无', '不吸烟', '做保险经纪人的，公司离漕河泾店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢篮球、养鱼、主机游戏、下厨。准备长住，至少两年。', '卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。能互相尊重彼此的空间就好。', '篮球,养鱼,主机游戏,下厨,城市漫步,甜品', NULL, '已通过', NULL, '2026-10-01 09:46:13', '是', '2026-10-01 09:26:37', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (199, 200, '洲之', '女', '1992-07-04 00:00:00', 3900, '整洁', '新媒体运营', '6-12个月', 5, '正常作息', '无', '不吸烟', '目前在徐汇做新媒体运营，想找个近一点的地方住。一般十二点前睡觉，周末会稍微睡个懒觉。东西习惯分类收纳，厨房用完当天就擦干净。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢听音乐会、卡牌、历史、乐器。打算先签一年以内。', '希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '听音乐会,卡牌,历史,乐器,心理学', NULL, '已通过', NULL, '2026-10-02 02:14:10', '是', '2026-10-02 02:09:36', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (200, 201, '江昭钧', '男', '1996-03-29 00:00:00', 2600, '随意', '健身教练', '3个月以下', 5, '正常作息', '无', '不吸烟', '做健身教练的，平时喜欢撸狗、看电影，人比较好相处。', '卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '撸狗,看电影,养鸟,舞蹈,拼图,爬宠', NULL, '已通过', NULL, '2026-10-01 05:23:26', '是', '2026-10-01 05:11:37', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (201, 202, '志奕', '男', '1994-12-15 00:00:00', 3500, '一般', '电气工程师', '6-12个月', 5, '早睡早起', '无', '不吸烟', '目前在徐汇做电气工程师，想找个近一点的地方住。我习惯早睡早起，晚上十一点之后基本就不出声了。公共区域愿意排值日轮流打扫。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢篮球、养狗、健身。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '篮球,养狗,健身', NULL, '已通过', NULL, '2026-10-01 18:55:56', '是', '2026-10-01 18:45:05', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (202, 203, '叙元', '男', '1994-06-22 00:00:00', 2200, '一般', '网约车司机', '6-12个月', 5, '早睡早起', '无', '不吸烟', '目前在徐汇做网约车司机，想找个近一点的地方住。我习惯早睡早起，晚上十一点之后基本就不出声了。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢密室逃脱、篮球、烘焙、滑雪。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。能互相尊重彼此的空间就好。', '密室逃脱,篮球,烘焙,滑雪', NULL, '已通过', NULL, '2026-10-02 16:22:41', '是', '2026-10-02 16:08:16', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (203, 204, '泽舟', '男', '1990-11-08 00:00:00', 4400, '随意', '前端工程师', '6-12个月', 5, '正常作息', '无', '不吸烟', '做前端工程师的，公司离漕河泾店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。对整洁要求不高，东西放得有点随意，不过不会影响别人。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢端游、跑步、看话剧、露营。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '端游,跑步,看话剧,露营,爬山,自驾游', NULL, '已通过', NULL, '2026-10-02 02:01:38', '是', '2026-10-02 01:45:07', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (204, 205, '柏昭', '男', '1997-03-15 00:00:00', 3500, '一般', '保险经纪人', '6-12个月', 5, '夜猫子', '无', '不吸烟', '做保险经纪人的，平时喜欢烘焙、舞蹈，人比较好相处。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '烘焙,舞蹈,看展,端游,摄影旅行', NULL, '已通过', NULL, '2026-10-01 22:36:41', '是', '2026-10-01 22:16:45', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (205, 206, '景瑾', '女', '1992-12-18 00:00:00', 2700, '洁癖', '界面设计师', '6-12个月', 5, '正常作息', '无', '不吸烟', '我在徐汇这边上班，做界面设计师。工作日朝九晚六，晚上偶尔追剧到十二点左右。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看综艺、探店、密室逃脱、撸猫。打算先签一年以内。', '希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '看综艺,探店,密室逃脱,撸猫,看纪录片,乐器', NULL, '已通过', NULL, '2026-10-03 03:01:44', '是', '2026-10-03 02:52:49', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (206, 207, '恒宸', '男', '1984-04-13 00:00:00', 4300, '整洁', '产品经理', '3-6个月', 5, '正常作息', '无', '不吸烟', '目前在徐汇做产品经理，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢密室逃脱、游泳、追剧、听相声。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '密室逃脱,游泳,追剧,听相声,主机游戏', NULL, '已通过', NULL, '2026-10-02 19:07:27', '是', '2026-10-02 19:01:39', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (207, 208, '瑾禾', '女', '1981-04-22 00:00:00', 3300, '随意', '编辑', '6-12个月', 5, '早睡早起', '无', '不吸烟', '做编辑的，公司离漕河泾店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。自己房间不算特别整齐，但公共区域用完会收拾。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢小说、历史、游泳、散文。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '小说,历史,游泳,散文,看话剧,品酒', NULL, '已通过', NULL, '2026-10-02 00:02:39', '是', '2026-10-01 23:51:04', '2026-10-03 21:10:17');
