INSERT INTO `member_profile` VALUES (245, 246, '语禾', '女', '1988-01-18 00:00:00', 1900, '一般', '电商运营', '1-2年', 6, '正常作息', '无', '不吸烟', '我在徐汇这边上班，做电商运营。一般十二点前睡觉，周末会稍微睡个懒觉。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢乐器、茶道、历史、绘画。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '乐器,茶道,历史,绘画,卡牌,诗集', NULL, '已通过', NULL, '2026-10-01 06:34:01', '是', '2026-10-01 06:13:07', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (246, 247, '楠禾', '女', '1985-01-28 00:00:00', 2300, '整洁', '电气工程师', '2年以上', 6, '早睡早起', '有', '不吸烟', '做电气工程师的，公司离徐家汇店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。比较爱干净，公共区域用完马上收拾。养了一只猫，很安静，猫砂每天清。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢烘焙、火锅、咖啡、宠物摄影。准备长住，至少两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望室友能接受我养的小宠物。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '烘焙,火锅,咖啡,宠物摄影,端游,骑行', NULL, '已通过', NULL, '2026-10-03 05:52:40', '是', '2026-10-03 05:39:40', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (247, 248, '清以', '女', '1995-11-16 00:00:00', 4400, '整洁', '摄影师', '1-2年', 6, '早睡早起', '有', '不吸烟', '目前在徐汇做摄影师，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。比较爱干净，公共区域用完马上收拾。养了一只猫，很安静，猫砂每天清。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢杂志、卡牌、养猫。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望室友能接受我养的小宠物。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '杂志,卡牌,养猫', NULL, '已通过', NULL, '2026-10-03 05:02:29', '是', '2026-10-03 04:51:53', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (248, 249, '若亭', '女', '2001-07-19 00:00:00', 2500, '随意', '行政专员', '6-12个月', 6, '正常作息', '无', '不吸烟', '做行政专员的，公司离徐家汇店不远。一般十二点前睡觉，周末会稍微睡个懒觉。对整洁要求不高，东西放得有点随意，不过不会影响别人。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看展、自驾游、养狗、爬宠。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '看展,自驾游,养狗,爬宠', NULL, '已通过', NULL, '2026-10-03 01:15:07', '是', '2026-10-03 01:11:01', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (249, 250, '宸川', '男', '1992-03-08 00:00:00', 2200, '一般', '公务员', '1-2年', 6, '正常作息', '无', '不吸烟', '目前在徐汇做公务员，想找个近一点的地方住。工作日朝九晚六，晚上偶尔追剧到十二点左右。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢宠物公益、跑步、桌游。工作稳定，计划在这边住一到两年。', '对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '宠物公益,跑步,桌游', NULL, '已通过', NULL, '2026-10-03 09:17:17', '是', '2026-10-03 08:54:21', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (250, 251, '梁时宇', '男', '1990-10-20 00:00:00', 3300, '随意', '电商运营', '1-2年', 6, '夜猫子', '无', '不吸烟', '做电商运营的，公司离徐家汇店不远。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。自己房间不算特别整齐，但公共区域用完会收拾。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢看展、品酒、看话剧、古镇游。工作稳定，计划在这边住一到两年。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '看展,品酒,看话剧,古镇游,手游,看电影', NULL, '已通过', NULL, '2026-10-01 23:44:30', '是', '2026-10-01 23:22:40', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (251, 252, '煜洲', '男', '1996-03-11 00:00:00', 3400, '整洁', '大学讲师', '1-2年', 6, '夜猫子', '有', '偶尔', '我在徐汇这边上班，做大学讲师。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。东西习惯分类收纳，厨房用完当天就擦干净。养了一只小狗，打过疫苗，每天早晚各遛一次。偶尔会抽烟，但只在楼下抽，不在屋里。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢绘画、咖啡、出境游、下厨。工作稳定，计划在这边住一到两年。', '我睡得晚，希望室友对作息不要太敏感。希望室友能接受我养的小宠物。相处简单一点，有事好商量。', '绘画,咖啡,出境游,下厨,宠物公益', NULL, '已通过', NULL, '2026-10-02 01:56:50', '是', '2026-10-02 01:53:23', '2026-10-03 21:10:17');
