INSERT INTO `member_profile` VALUES (278, 279, '亭筱', '女', '1995-08-10 00:00:00', 4900, '随意', '编辑', '6-12个月', 7, '正常作息', '无', '偶尔', '目前在徐汇做编辑，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。自己房间不算特别整齐，但公共区域用完会收拾。偶尔会抽烟，但只在楼下抽，不在屋里。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢传记、背包客、绘画、经济学。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '传记,背包客,绘画,经济学,手游', NULL, '已通过', NULL, '2026-10-01 23:05:09', '是', '2026-10-01 22:45:11', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (279, 280, '书清', '女', '2003-07-07 00:00:00', 2600, '随意', '理财顾问', '3-6个月', 7, '正常作息', '无', '不吸烟', '我在徐汇这边上班，做理财顾问。作息算正常，十二点左右睡，早上八点前起。自己房间不算特别整齐，但公共区域用完会收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢乒乓球、自驾游、宠物摄影、古镇游。项目驻场半年左右，计划租三到六个月。', '卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。相处简单一点，有事好商量。', '乒乓球,自驾游,宠物摄影,古镇游,健身,烘焙', NULL, '已通过', NULL, '2026-10-03 13:51:42', '否', '2026-10-03 13:49:58', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (280, 281, '宋念云', '女', '2002-08-08 00:00:00', 4100, '整洁', '消防员', '1-2年', 7, '正常作息', '无', '经常', '做消防员的，公司离龙华店不远。一般十二点前睡觉，周末会稍微睡个懒觉。东西习惯分类收纳，厨房用完当天就擦干净。有抽烟的习惯，会尽量去阳台或楼下抽。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢传记、摄影、宠物摄影。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '传记,摄影,宠物摄影', NULL, '已通过', NULL, '2026-10-03 06:33:18', '是', '2026-10-03 06:10:43', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (281, 282, '以洲', '女', '1997-09-14 00:00:00', 2000, '整洁', '录音师', '6-12个月', 7, '夜猫子', '无', '不吸烟', '目前在徐汇做录音师，想找个近一点的地方住。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。比较爱干净，公共区域用完马上收拾。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢舞蹈、健身、烧烤、探店。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '舞蹈,健身,烧烤,探店', NULL, '已通过', NULL, '2026-10-01 13:54:29', '是', '2026-10-01 13:44:08', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (282, 283, '亦文', '男', '1985-04-17 00:00:00', 3200, '洁癖', '机械工程师', '6-12个月', 7, '正常作息', '有', '不吸烟', '做机械工程师的，公司离龙华店不远。作息算正常，十二点左右睡，早上八点前起。有点洁癖，卫生间和厨房希望每次用完都擦干。养了一只小狗，打过疫苗，每天早晚各遛一次。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢徒步、听播客、茶道、篮球。打算先签一年以内。', '希望室友爱干净，公共区域用完能及时收拾。希望室友能接受我养的小宠物。能互相尊重彼此的空间就好。', '徒步,听播客,茶道,篮球,探店,烘焙', NULL, '已通过', NULL, '2026-10-01 01:31:45', '是', '2026-10-01 01:07:33', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (283, 284, '彤清', '女', '1994-06-30 00:00:00', 5000, '洁癖', '民警', '6-12个月', 7, '正常作息', '无', '不吸烟', '做民警的，平时喜欢城市漫步、看电影，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。能互相尊重彼此的空间就好。', '城市漫步,看电影,爬宠,古镇游,瑜伽,出境游', NULL, '已通过', NULL, '2026-10-02 20:22:46', '是', '2026-10-02 20:04:52', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (284, 285, '然砚', '男', '1986-10-27 00:00:00', 3700, '一般', '财务经理', '6-12个月', 7, '夜猫子', '无', '不吸烟', '我在徐汇这边上班，做财务经理。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。公共区域愿意排值日轮流打扫。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢日料、插画、海岛游、舞蹈。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '日料,插画,海岛游,舞蹈,宠物公益', NULL, '已通过', NULL, '2026-10-02 14:49:16', '是', '2026-10-02 14:27:25', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (285, 286, '莹禾', '女', '1992-08-19 00:00:00', 3900, '随意', '空乘', '6-12个月', 7, '正常作息', '无', '不吸烟', '做空乘的，平时喜欢杂志、养仓鼠，人比较好相处。', '卫生方面大家互相体谅就好。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '杂志,养仓鼠,散文,养鱼', NULL, '已通过', NULL, '2026-10-01 07:59:45', '是', '2026-10-01 07:40:14', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (286, 287, '晚星', '女', '1992-08-01 00:00:00', 4000, '整洁', '软件工程师', '2年以上', 7, '夜猫子', '无', '不吸烟', '我在徐汇这边上班，做软件工程师。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看纪录片、电竞、桌游。准备长住，至少两年。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。如果能偶尔一起做饭就更好了。', '看纪录片,电竞,桌游', NULL, '已通过', NULL, '2026-10-02 11:58:00', '是', '2026-10-02 11:42:55', '2026-10-03 21:10:17');
