INSERT INTO `member_profile` VALUES (295, 296, '铭宇', '男', '2000-05-28 00:00:00', 3900, '一般', '心理咨询师', '3-6个月', 7, '正常作息', '无', '不吸烟', '我在徐汇这边上班，做心理咨询师。作息算正常，十二点左右睡，早上八点前起。公共区域愿意排值日轮流打扫。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢诗集、养仓鼠、卡牌。项目驻场半年左右，计划租三到六个月。', '希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '诗集,养仓鼠,卡牌', NULL, '已通过', NULL, '2026-10-01 04:52:23', '是', '2026-10-01 04:41:50', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (296, 297, '林宸', '男', '2004-07-21 00:00:00', 4200, '随意', '后端工程师', '6-12个月', 7, '早睡早起', '无', '不吸烟', '做后端工程师的，平时喜欢下厨、卡牌，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '下厨,卡牌,杂志,追剧', NULL, '已通过', NULL, '2026-10-01 15:48:19', '是', '2026-10-01 15:41:09', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (297, 298, '亦昭', '男', '2000-10-19 00:00:00', 4000, '洁癖', '宠物医生', '1-2年', 7, '正常作息', '无', '不吸烟', '我在徐汇这边上班，做宠物医生。作息算正常，十二点左右睡，早上八点前起。有点洁癖，卫生间和厨房希望每次用完都擦干。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢骑行、棋类、看话剧、乒乓球。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '骑行,棋类,看话剧,乒乓球,电竞,房车旅行', NULL, '已通过', NULL, '2026-10-02 03:40:03', '是', '2026-10-02 03:36:13', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (298, 299, '煜书', '男', '1984-03-09 00:00:00', 2400, '整洁', '行政专员', '3个月以下', 7, '正常作息', '无', '不吸烟', '做行政专员的，公司离龙华店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。比较爱干净，公共区域用完马上收拾。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢书法、哲学、骑行。最近是过渡期，先住两三个月看看。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。如果能偶尔一起做饭就更好了。', '书法,哲学,骑行', NULL, '已通过', NULL, '2026-10-02 15:38:50', '是', '2026-10-02 15:18:56', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (299, 300, '然树', '男', '1998-08-03 00:00:00', 3700, '洁癖', '物流主管', '2年以上', 7, '正常作息', '无', '不吸烟', '做物流主管的，平时喜欢心理学、养鸟，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '心理学,养鸟,追剧,科幻,火锅,剧本杀', NULL, '已通过', NULL, '2026-10-01 15:20:24', '是', '2026-10-01 14:53:36', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (300, 301, '崔婉慕', '女', '2000-04-19 00:00:00', 3200, '一般', '后端工程师', '6-12个月', 7, '早睡早起', '无', '不吸烟', '目前在徐汇做后端工程师，想找个近一点的地方住。我习惯早睡早起，晚上十一点之后基本就不出声了。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢滑雪、乐器、听音乐、养猫。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '滑雪,乐器,听音乐,养猫,自驾游,拼图', NULL, '已通过', NULL, '2026-10-01 04:09:46', '是', '2026-10-01 03:44:05', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (301, 302, '朗云', '男', '2001-08-20 00:00:00', 1900, '一般', '行政专员', '6-12个月', 7, '夜猫子', '无', '不吸烟', '做行政专员的，公司离龙华店不远。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看纪录片、密室逃脱、棋类。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '看纪录片,密室逃脱,棋类', NULL, '已通过', NULL, '2026-10-02 07:02:00', '是', '2026-10-02 06:47:34', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (302, 303, '越皓', '男', '2002-09-01 00:00:00', 4800, '洁癖', '社区工作者', '6-12个月', 7, '正常作息', '无', '偶尔', '我在徐汇这边上班，做社区工作者。作息算正常，十二点左右睡，早上八点前起。有点洁癖，卫生间和厨房希望每次用完都擦干。偶尔会抽烟，但只在楼下抽，不在屋里。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢日料、摄影旅行、桌游、游泳。打算先签一年以内。', '希望室友爱干净，公共区域用完能及时收拾。如果能偶尔一起做饭就更好了。', '日料,摄影旅行,桌游,游泳,历史', NULL, '已通过', NULL, '2026-10-01 17:07:12', '是', '2026-10-01 17:05:39', '2026-10-03 21:10:17');
