INSERT INTO `member_profile` VALUES (312, 313, '林钧', '男', '1984-11-27 00:00:00', 2000, '一般', '软件工程师', '1-2年', 7, '正常作息', '无', '不吸烟', '做软件工程师的，平时喜欢书法、养狗，人比较好相处。', '卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '书法,养狗,散文,养鸟,绘画', NULL, '已通过', NULL, '2026-10-02 17:18:38', '是', '2026-10-02 17:13:05', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (313, 314, '雨晚', '女', '1996-04-11 00:00:00', 3200, '一般', '前端工程师', '2年以上', 7, '正常作息', '无', '不吸烟', '目前在徐汇做前端工程师，想找个近一点的地方住。工作日朝九晚六，晚上偶尔追剧到十二点左右。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢下厨、电竞、听音乐会、爬宠。准备长住，至少两年。', '相处简单一点，有事好商量。', '下厨,电竞,听音乐会,爬宠,品酒', NULL, '已通过', NULL, '2026-10-01 12:08:04', '是', '2026-10-01 11:56:41', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (314, 315, '舒怡', '女', '1988-01-09 00:00:00', 3800, '一般', '物流主管', '6-12个月', 7, '早睡早起', '无', '不吸烟', '做物流主管的，公司离龙华店不远。每天七点前起床晨跑，晚上很少熬夜。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢乐器、爬山、撸狗、羽毛球。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '乐器,爬山,撸狗,羽毛球,看综艺,历史', NULL, '已通过', NULL, '2026-10-03 14:14:13', '是', '2026-10-03 14:12:48', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (315, 316, '书知', '女', '1990-10-01 00:00:00', 3400, '洁癖', '采购专员', '6-12个月', 7, '正常作息', '无', '不吸烟', '做采购专员的，平时喜欢科幻、手工，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '科幻,手工,烧烤', NULL, '已通过', NULL, '2026-10-02 13:15:55', '是', '2026-10-02 12:53:32', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (316, 317, '以宁', '女', '1996-06-29 00:00:00', 3800, '随意', '市场专员', '3-6个月', 8, '早睡早起', '有', '不吸烟', '我在徐汇这边上班，做市场专员。每天七点前起床晨跑，晚上很少熬夜。自己房间不算特别整齐，但公共区域用完会收拾。养了一只小狗，打过疫苗，每天早晚各遛一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢电竞、甜品、古镇游、科幻。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望室友能接受我养的小宠物。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '电竞,甜品,古镇游,科幻,养鱼', NULL, '待审核', NULL, NULL, '是', '2026-10-01 14:14:11', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (317, 318, '宇砚', '男', '1989-06-15 00:00:00', 4700, '洁癖', '行政专员', '6-12个月', 8, '正常作息', '无', '不吸烟', '做行政专员的，公司离田林店不远。作息算正常，十二点左右睡，早上八点前起。有点洁癖，卫生间和厨房希望每次用完都擦干。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢宠物公益、乒乓球、绘画、撸猫。打算先签一年以内。', '卫生方面大家互相体谅就好。能互相尊重彼此的空间就好。', '宠物公益,乒乓球,绘画,撸猫,看电影,乐器', NULL, '已驳回', '相册里有与本人不符的照片，请重新上传后再提交', '2026-10-01 05:43:37', '是', '2026-10-01 05:35:31', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (318, 319, '行锦', '男', '2000-05-22 00:00:00', 1900, '整洁', '财务经理', '6-12个月', 8, '夜猫子', '无', '不吸烟', '做财务经理的，公司离田林店不远。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢卡牌、舞蹈、品酒、健身。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '卡牌,舞蹈,品酒,健身,陶艺', NULL, '已通过', NULL, '2026-10-03 05:15:09', '是', '2026-10-03 04:59:58', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (319, 320, '锐亦', '男', '1993-11-16 00:00:00', 3100, '随意', '招聘主管', '1-2年', 8, '正常作息', '有', '不吸烟', '目前在徐汇做招聘主管，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。对整洁要求不高，东西放得有点随意，不过不会影响别人。养了一只猫，很安静，猫砂每天清。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢出境游、养猫、书法。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友能接受我养的小宠物。能互相尊重彼此的空间就好。', '出境游,养猫,书法', NULL, '已通过', NULL, '2026-10-03 08:04:57', '是', '2026-10-03 07:49:10', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (320, 321, '王砚涵', '男', '1989-05-23 00:00:00', 3900, '洁癖', '中学教师', '2年以上', 8, '夜猫子', '无', '不吸烟', '做中学教师的，公司离田林店不远。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢品酒、书法、经济学、主机游戏。准备长住，至少两年。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '品酒,书法,经济学,主机游戏', NULL, '已通过', NULL, '2026-10-01 10:33:45', '是', '2026-10-01 10:11:05', '2026-10-03 21:10:17');
