INSERT INTO `member_profile` VALUES (345, 346, '林雨', '女', '2004-02-23 00:00:00', 3400, '一般', '摄影师', '1-2年', 8, '正常作息', '无', '不吸烟', '做摄影师的，公司离田林店不远。一般十二点前睡觉，周末会稍微睡个懒觉。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢哲学、甜品、骑行、咖啡。工作稳定，计划在这边住一到两年。', '希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '哲学,甜品,骑行,咖啡,心理学,撸狗', NULL, '已通过', NULL, '2026-10-01 22:45:15', '是', '2026-10-01 22:25:12', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (346, 347, '舟皓', '男', '2002-01-08 00:00:00', 5300, '随意', '编辑', '1-2年', 8, '正常作息', '有', '不吸烟', '目前在徐汇做编辑，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。对整洁要求不高，东西放得有点随意，不过不会影响别人。养了一只小狗，打过疫苗，每天早晚各遛一次。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢徒步、看话剧、听音乐会、插画。工作稳定，计划在这边住一到两年。', '卫生方面大家互相体谅就好。希望室友能接受我养的小宠物。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '徒步,看话剧,听音乐会,插画,手游', NULL, '已通过', NULL, '2026-10-01 13:35:00', '是', '2026-10-01 13:32:54', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (347, 348, '墨楚', '女', '2001-01-27 00:00:00', 4400, '一般', '法务专员', '6-12个月', 8, '早睡早起', '无', '不吸烟', '我在徐汇这边上班，做法务专员。我习惯早睡早起，晚上十一点之后基本就不出声了。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢看展、爬宠、古镇游、绘画。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。如果能偶尔一起做饭就更好了。', '看展,爬宠,古镇游,绘画,乐器,背包客', NULL, '已通过', NULL, '2026-10-01 13:12:42', '是', '2026-10-01 13:00:46', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (348, 349, '砚川', '男', '1985-09-18 00:00:00', 3200, '一般', '舞台灯光师', '6-12个月', 8, '正常作息', '无', '不吸烟', '目前在徐汇做舞台灯光师，想找个近一点的地方住。一般十二点前睡觉，周末会稍微睡个懒觉。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢养鸟、唱歌、露营、密室逃脱。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '养鸟,唱歌,露营,密室逃脱', NULL, '已通过', NULL, '2026-10-02 23:08:14', '是', '2026-10-02 22:58:17', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (349, 350, '芸景', '女', '2001-02-10 00:00:00', 3700, '洁癖', '园艺师', '2年以上', 8, '正常作息', '无', '不吸烟', '做园艺师的，公司离田林店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。对卫生要求比较高，每周会给公共区域做一次深度清洁。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢健身、下厨、听相声、品酒。准备长住，至少两年。', '卫生方面大家互相体谅就好。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '健身,下厨,听相声,品酒', NULL, '已通过', NULL, '2026-10-01 03:34:36', '是', '2026-10-01 03:06:20', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (350, 351, '刘涵钧', '男', '1991-03-22 00:00:00', 4100, '整洁', '医生', '1-2年', 8, '早睡早起', '无', '不吸烟', '目前在徐汇做医生，想找个近一点的地方住。作息很规律，一般十点半前睡，早上六点多就起了。比较爱干净，公共区域用完马上收拾。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢棋类、背包客、乒乓球、烘焙。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '棋类,背包客,乒乓球,烘焙,徒步,唱歌', NULL, '已通过', NULL, '2026-10-03 16:42:04', '是', '2026-10-03 16:32:52', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (351, 352, '志皓', '男', '1993-02-09 00:00:00', 5600, '随意', '餐饮店主', '1-2年', 8, '早睡早起', '无', '不吸烟', '目前在徐汇做餐饮店主，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。自己房间不算特别整齐，但公共区域用完会收拾。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢下厨、传记、养仓鼠、养狗。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '下厨,传记,养仓鼠,养狗,撸猫,篮球', NULL, '已通过', NULL, '2026-10-02 02:54:20', '是', '2026-10-02 02:37:32', '2026-10-03 21:10:17');
