INSERT INTO `member_profile` VALUES (369, 370, '清尘', '女', '1987-10-17 00:00:00', 4400, '整洁', '后端工程师', '6-12个月', 9, '早睡早起', '无', '经常', '做后端工程师的，公司离五角场店不远。每天七点前起床晨跑，晚上很少熬夜。比较爱干净，公共区域用完马上收拾。有抽烟的习惯，会尽量去阳台或楼下抽。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢跑步、电竞、听播客、杂志。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。如果能偶尔一起做饭就更好了。', '跑步,电竞,听播客,杂志,端游,科幻', NULL, '已通过', NULL, '2026-10-01 14:24:36', '是', '2026-10-01 14:03:44', '2026-10-03 21:10:17');
