INSERT INTO `member_profile` VALUES (493, 494, '洛筱', '女', '1996-10-02 00:00:00', 3500, '洁癖', '人力资源专员', '6-12个月', 11, '早睡早起', '无', '不吸烟', '目前在杨浦做人力资源专员，想找个近一点的地方住。我习惯早睡早起，晚上十一点之后基本就不出声了。有点洁癖，卫生间和厨房希望每次用完都擦干。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢传记、小说、爬宠、桌游。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。如果能偶尔一起做饭就更好了。', '传记,小说,爬宠,桌游,火锅', NULL, '已通过', NULL, '2026-10-03 10:18:11', '是', '2026-10-03 10:12:22', '2026-10-03 21:10:17');
