INSERT INTO `member_profile` VALUES (577, 578, '恒轩', '男', '1987-06-07 00:00:00', 5500, '一般', '药剂师', '1-2年', 13, '早睡早起', '无', '不吸烟', '做药剂师的，平时喜欢养鸟、烧烤，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '养鸟,烧烤,篮球', NULL, '已通过', NULL, '2026-10-02 10:03:55', '是', '2026-10-02 09:42:22', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (578, 579, '航树', '男', '1994-08-04 00:00:00', 2000, '洁癖', '后端工程师', '6-12个月', 13, '夜猫子', '无', '不吸烟', '我在闵行这边上班，做后端工程师。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢露营、经济学、品酒、历史。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。能互相尊重彼此的空间就好。', '露营,经济学,品酒,历史', NULL, '已通过', NULL, '2026-10-02 06:41:58', '是', '2026-10-02 06:36:09', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (579, 580, '明屿', '男', '1984-05-30 00:00:00', 3700, '一般', '房产经纪', '6-12个月', 13, '正常作息', '无', '偶尔', '我在闵行这边上班，做房产经纪。一般十二点前睡觉，周末会稍微睡个懒觉。公共区域愿意排值日轮流打扫。偶尔会抽烟，但只在楼下抽，不在屋里。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢跑步、品酒、养鸟、骑行。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '跑步,品酒,养鸟,骑行,看综艺,养狗', NULL, '已通过', NULL, '2026-10-01 21:14:39', '是', '2026-10-01 20:55:11', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (580, 581, '毛韵景', '女', '1983-04-25 00:00:00', 3000, '洁癖', '新媒体运营', '1-2年', 13, '正常作息', '无', '不吸烟', '做新媒体运营的，公司离莘庄店不远。作息算正常，十二点左右睡，早上八点前起。有点洁癖，卫生间和厨房希望每次用完都擦干。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢陶艺、咖啡、火锅、茶道。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '陶艺,咖啡,火锅,茶道,看综艺', NULL, '待审核', NULL, NULL, '是', '2026-10-02 17:12:37', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (581, 582, '亦航', '男', '1989-11-17 00:00:00', 3700, '洁癖', '健身教练', '6-12个月', 13, '早睡早起', '有', '经常', '我在闵行这边上班，做健身教练。作息很规律，一般十点半前睡，早上六点多就起了。有点洁癖，卫生间和厨房希望每次用完都擦干。养了一只小狗，打过疫苗，每天早晚各遛一次。有抽烟的习惯，会尽量去阳台或楼下抽。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢听播客、密室逃脱、传记、爬山。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望室友能接受我养的小宠物。能互相尊重彼此的空间就好。', '听播客,密室逃脱,传记,爬山,手工', NULL, '已通过', NULL, '2026-10-03 04:31:22', '是', '2026-10-03 04:16:57', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (582, 583, '雨宁', '女', '1994-03-04 00:00:00', 3300, '随意', '数据分析师', '1-2年', 13, '早睡早起', '无', '不吸烟', '我在闵行这边上班，做数据分析师。我习惯早睡早起，晚上十一点之后基本就不出声了。自己房间不算特别整齐，但公共区域用完会收拾。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢探店、骑行、海岛游。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '探店,骑行,海岛游', NULL, '已通过', NULL, '2026-10-02 12:41:43', '是', '2026-10-02 12:12:55', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (583, 584, '钧谦', '男', '1993-03-14 00:00:00', 2400, '一般', '外贸业务员', '1-2年', 13, '夜猫子', '无', '不吸烟', '做外贸业务员的，公司离莘庄店不远。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢看话剧、听播客、健身、滑雪。工作稳定，计划在这边住一到两年。', '我睡得晚，希望室友对作息不要太敏感。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '看话剧,听播客,健身,滑雪,茶道,撸猫', NULL, '已通过', NULL, '2026-10-02 18:21:31', '是', '2026-10-02 17:53:23', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (584, 585, '楚南', '女', '1987-10-28 00:00:00', 3200, '整洁', '财务经理', '6-12个月', 13, '夜猫子', '无', '不吸烟', '目前在闵行做财务经理，想找个近一点的地方住。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢养鸟、健身、宠物摄影。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '养鸟,健身,宠物摄影', NULL, '已通过', NULL, '2026-10-02 14:48:36', '是', '2026-10-02 14:30:40', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (585, 586, '志恒', '男', '1986-03-16 00:00:00', 3700, '随意', '厨师', '6-12个月', 13, '正常作息', '无', '经常', '我在闵行这边上班，做厨师。工作日朝九晚六，晚上偶尔追剧到十二点左右。自己房间不算特别整齐，但公共区域用完会收拾。有抽烟的习惯，会尽量去阳台或楼下抽。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢摄影旅行、乒乓球、出境游、撸狗。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '摄影旅行,乒乓球,出境游,撸狗,游泳,滑雪', NULL, '已通过', NULL, '2026-10-02 11:10:01', '是', '2026-10-02 11:03:16', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (586, 587, '楠芸', '女', '1998-09-14 00:00:00', 2600, '洁癖', '中学教师', '6-12个月', 14, '夜猫子', '无', '不吸烟', '我在闵行这边上班，做中学教师。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。对卫生要求比较高，每周会给公共区域做一次深度清洁。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看综艺、出境游、乐器、杂志。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '看综艺,出境游,乐器,杂志,跑步,密室逃脱', NULL, '待审核', NULL, NULL, '是', '2026-10-01 23:47:12', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (587, 588, '亭思', '女', '1987-11-26 00:00:00', 2000, '洁癖', '市场专员', '3个月以下', 14, '夜猫子', '无', '不吸烟', '我在闵行这边上班，做市场专员。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢书法、养仓鼠、插画、篮球。最近是过渡期，先住两三个月看看。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '书法,养仓鼠,插画,篮球,养鱼,手工', NULL, '已驳回', '相册里有与本人不符的照片，请重新上传后再提交', '2026-10-02 15:08:15', '是', '2026-10-02 15:04:52', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (588, 589, '楠尘', '女', '2002-04-22 00:00:00', 3800, '随意', '平面设计师', '2年以上', 14, '早睡早起', '无', '不吸烟', '我在闵行这边上班，做平面设计师。我习惯早睡早起，晚上十一点之后基本就不出声了。对整洁要求不高，东西放得有点随意，不过不会影响别人。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看纪录片、听播客、日料、小说。准备长住，至少两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '看纪录片,听播客,日料,小说,端游,古镇游', NULL, '已通过', NULL, '2026-10-02 05:21:31', '是', '2026-10-02 05:12:59', '2026-10-03 21:10:17');
