INSERT INTO `member_profile` VALUES (601, 602, '彤以', '女', '1983-06-09 00:00:00', 4500, '随意', '空乘', '6-12个月', 14, '早睡早起', '有', '不吸烟', '做空乘的，公司离七宝店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。自己房间不算特别整齐，但公共区域用完会收拾。养了一只小狗，打过疫苗，每天早晚各遛一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢经济学、乐器、甜品、品酒。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友能接受我养的小宠物。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '经济学,乐器,甜品,品酒', NULL, '已通过', NULL, '2026-10-01 20:15:51', '是', '2026-10-01 19:58:17', '2026-10-03 21:10:17');
