INSERT INTO `member_profile` VALUES (655, 656, '昱嘉', '男', '1997-01-16 00:00:00', 4200, '一般', '药剂师', '3个月以下', 15, '正常作息', '无', '不吸烟', '做药剂师的，公司离虹桥枢纽店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢养仓鼠、看电影、宠物公益。最近是过渡期，先住两三个月看看。', '卫生方面大家互相体谅就好。能互相尊重彼此的空间就好。', '养仓鼠,看电影,宠物公益', NULL, '已通过', NULL, '2026-10-03 04:59:37', '是', '2026-10-03 04:56:37', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (656, 657, '宇砚', '男', '1999-04-26 00:00:00', 3800, '洁癖', '电气工程师', '2年以上', 15, '夜猫子', '有', '不吸烟', '目前在闵行做电气工程师，想找个近一点的地方住。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。有点洁癖，卫生间和厨房希望每次用完都擦干。养了一只小狗，打过疫苗，每天早晚各遛一次。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢陶艺、哲学、健身。准备长住，至少两年。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。希望室友能接受我养的小宠物。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '陶艺,哲学,健身', NULL, '已通过', NULL, '2026-10-01 13:56:18', '是', '2026-10-01 13:47:12', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (657, 658, '昱洲', '男', '1984-12-22 00:00:00', 1800, '一般', '公务员', '3个月以下', 15, '正常作息', '无', '不吸烟', '做公务员的，公司离虹桥枢纽店不远。一般十二点前睡觉，周末会稍微睡个懒觉。公共区域愿意排值日轮流打扫。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢游泳、品酒、看话剧、电竞。最近是过渡期，先住两三个月看看。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '游泳,品酒,看话剧,电竞,滑雪,插画', NULL, '已通过', NULL, '2026-10-02 22:00:32', '是', '2026-10-02 21:41:37', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (658, 659, '怡以', '女', '1992-01-17 00:00:00', 4500, '整洁', '数据分析师', '6-12个月', 15, '早睡早起', '有', '不吸烟', '做数据分析师的，公司离虹桥枢纽店不远。每天七点前起床晨跑，晚上很少熬夜。比较爱干净，公共区域用完马上收拾。养了一只小狗，打过疫苗，每天早晚各遛一次。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢舞蹈、茶道、看话剧、烘焙。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望室友能接受我养的小宠物。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '舞蹈,茶道,看话剧,烘焙,手工', NULL, '已通过', NULL, '2026-10-01 18:51:02', '是', '2026-10-01 18:48:03', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (659, 660, '奕川', '男', '2000-04-27 00:00:00', 3400, '随意', '医生', '3-6个月', 15, '正常作息', '无', '不吸烟', '做医生的，公司离虹桥枢纽店不远。一般十二点前睡觉，周末会稍微睡个懒觉。自己房间不算特别整齐，但公共区域用完会收拾。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢摄影、科幻、下厨、乒乓球。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '摄影,科幻,下厨,乒乓球', NULL, '已通过', NULL, '2026-10-01 17:36:41', '是', '2026-10-01 17:10:27', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (660, 661, '杨汐芸', '女', '1994-06-15 00:00:00', 3100, '随意', '网络工程师', '1-2年', 15, '正常作息', '有', '不吸烟', '我在闵行这边上班，做网络工程师。作息算正常，十二点左右睡，早上八点前起。对整洁要求不高，东西放得有点随意，不过不会影响别人。养了一只小狗，打过疫苗，每天早晚各遛一次。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢听播客、拼图、篮球、撸狗。工作稳定，计划在这边住一到两年。', '希望室友能接受我养的小宠物。如果能偶尔一起做饭就更好了。', '听播客,拼图,篮球,撸狗', NULL, '已通过', NULL, '2026-10-02 00:16:54', '是', '2026-10-02 00:14:20', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (661, 662, '涵宇', '男', '1981-03-20 00:00:00', 4100, '一般', '平面设计师', '3-6个月', 15, '正常作息', '无', '不吸烟', '我在闵行这边上班，做平面设计师。工作日朝九晚六，晚上偶尔追剧到十二点左右。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢甜品、看动漫、看纪录片、宠物公益。项目驻场半年左右，计划租三到六个月。', '对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '甜品,看动漫,看纪录片,宠物公益,养鸟,乒乓球', NULL, '已通过', NULL, '2026-10-02 02:58:44', '是', '2026-10-02 02:36:11', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (662, 663, '晚之', '女', '1986-10-13 00:00:00', 2000, '整洁', '银行柜员', '6-12个月', 15, '正常作息', '无', '不吸烟', '做银行柜员的，平时喜欢下厨、自驾游，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。能互相尊重彼此的空间就好。', '下厨,自驾游,撸狗,养仓鼠,跑步,爬宠', NULL, '已通过', NULL, '2026-10-02 17:35:33', '是', '2026-10-02 17:14:52', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (663, 664, '亦行', '男', '1989-05-24 00:00:00', 2300, '一般', '土木工程师', '6-12个月', 15, '早睡早起', '无', '不吸烟', '我在闵行这边上班，做土木工程师。我习惯早睡早起，晚上十一点之后基本就不出声了。公共区域愿意排值日轮流打扫。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢篮球、桌游、听音乐。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '篮球,桌游,听音乐', NULL, '已通过', NULL, '2026-10-03 17:27:28', '是', '2026-10-03 17:06:53', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (664, 665, '莹之', '女', '2001-08-13 00:00:00', 2900, '一般', '平面设计师', '1-2年', 15, '夜猫子', '无', '不吸烟', '目前在闵行做平面设计师，想找个近一点的地方住。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢古镇游、出境游、跑步、杂志。工作稳定，计划在这边住一到两年。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '古镇游,出境游,跑步,杂志,养狗,听播客', NULL, '已通过', NULL, '2026-10-02 17:06:00', '是', '2026-10-02 16:53:45', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (665, 666, '锦靖', '男', '1995-12-16 00:00:00', 4300, '洁癖', '厨师', '2年以上', 15, '早睡早起', '无', '经常', '目前在闵行做厨师，想找个近一点的地方住。作息很规律，一般十点半前睡，早上六点多就起了。对卫生要求比较高，每周会给公共区域做一次深度清洁。有抽烟的习惯，会尽量去阳台或楼下抽。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢撸狗、哲学、陶艺。准备长住，至少两年。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '撸狗,哲学,陶艺', NULL, '已通过', NULL, '2026-10-03 09:16:09', '是', '2026-10-03 09:00:46', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (666, 667, '芸心', '女', '2000-06-05 00:00:00', 2000, '洁癖', '体育教练', '1-2年', 15, '夜猫子', '无', '不吸烟', '做体育教练的，公司离虹桥枢纽店不远。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢火锅、看纪录片、养鱼、养鸟。工作稳定，计划在这边住一到两年。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '火锅,看纪录片,养鱼,养鸟,看电影', NULL, '已通过', NULL, '2026-10-01 16:06:10', '是', '2026-10-01 15:49:18', '2026-10-03 21:10:17');
