INSERT INTO `member_profile` VALUES (689, 690, '韵清', '女', '1984-09-10 00:00:00', 2900, '一般', '采购专员', '1-2年', 16, '正常作息', '无', '不吸烟', '我在闵行这边上班，做采购专员。一般十二点前睡觉，周末会稍微睡个懒觉。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢陶艺、剧本杀、跑步。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '陶艺,剧本杀,跑步', NULL, '已通过', NULL, '2026-10-01 16:15:21', '是', '2026-10-01 16:04:45', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (690, 691, '赖岚洛', '女', '1991-11-05 00:00:00', 4000, '一般', '测绘工程师', '2年以上', 16, '早睡早起', '无', '不吸烟', '做测绘工程师的，公司离紫竹店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢养鱼、撸狗、书法、传记。准备长住，至少两年。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '养鱼,撸狗,书法,传记', NULL, '已通过', NULL, '2026-10-01 03:55:25', '是', '2026-10-01 03:30:26', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (691, 692, '航奕', '男', '1999-02-10 00:00:00', 3600, '整洁', '律师', '6-12个月', 16, '夜猫子', '无', '不吸烟', '我在闵行这边上班，做律师。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢出境游、经济学、看话剧、滑雪。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '出境游,经济学,看话剧,滑雪', NULL, '已通过', NULL, '2026-10-03 04:26:43', '是', '2026-10-03 04:09:29', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (692, 693, '谦松', '男', '1986-11-02 00:00:00', 3500, '一般', '消防员', '2年以上', 16, '正常作息', '无', '不吸烟', '做消防员的，公司离紫竹店不远。作息算正常，十二点左右睡，早上八点前起。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢撸猫、历史、追剧、端游。准备长住，至少两年。', '相处简单一点，有事好商量。', '撸猫,历史,追剧,端游', NULL, '已通过', NULL, '2026-10-03 00:07:53', '是', '2026-10-02 23:57:58', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (693, 694, '时朗', '男', '1994-05-26 00:00:00', 3400, '一般', '网络工程师', '1-2年', 16, '正常作息', '无', '不吸烟', '做网络工程师的，公司离紫竹店不远。作息算正常，十二点左右睡，早上八点前起。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢露营、科幻、背包客、历史。工作稳定，计划在这边住一到两年。', '卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '露营,科幻,背包客,历史', NULL, '已通过', NULL, '2026-10-02 09:53:19', '是', '2026-10-02 09:41:52', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (694, 695, '汐芸', '女', '2004-02-04 00:00:00', 3300, '洁癖', '民警', '6-12个月', 16, '早睡早起', '无', '不吸烟', '我在闵行这边上班，做民警。每天七点前起床晨跑，晚上很少熬夜。对卫生要求比较高，每周会给公共区域做一次深度清洁。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢散文、露营、手工。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '散文,露营,手工', NULL, '已通过', NULL, '2026-10-01 10:36:17', '是', '2026-10-01 10:13:57', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (695, 696, '禾韵', '女', '1990-03-20 00:00:00', 3600, '一般', '瑜伽教练', '2年以上', 16, '早睡早起', '无', '不吸烟', '我在闵行这边上班，做瑜伽教练。每天七点前起床晨跑，晚上很少熬夜。公共区域愿意排值日轮流打扫。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢健身、摄影、宠物公益。准备长住，至少两年。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '健身,摄影,宠物公益', NULL, '已通过', NULL, '2026-10-03 00:56:30', '是', '2026-10-03 00:54:41', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (696, 697, '钧程', '男', '1996-07-09 00:00:00', 4200, '一般', '算法工程师', '3-6个月', 16, '早睡早起', '无', '不吸烟', '做算法工程师的，平时喜欢看纪录片、小说，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '看纪录片,小说,卡牌,看展', NULL, '已通过', NULL, '2026-10-02 23:30:02', '是', '2026-10-02 23:14:22', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (697, 698, '柏然', '男', '1999-09-26 00:00:00', 4000, '洁癖', '药剂师', '3-6个月', 16, '正常作息', '无', '经常', '做药剂师的，公司离紫竹店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。有点洁癖，卫生间和厨房希望每次用完都擦干。有抽烟的习惯，会尽量去阳台或楼下抽。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢养仓鼠、绘画、棋类。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '养仓鼠,绘画,棋类', NULL, '已通过', NULL, '2026-10-03 15:05:14', '是', '2026-10-03 14:58:54', '2026-10-03 21:10:17');
