INSERT INTO `member_profile` VALUES (706, 707, '云亦', '男', '1989-07-18 00:00:00', 3800, '整洁', '审计师', '1-2年', 16, '正常作息', '无', '不吸烟', '我在闵行这边上班，做审计师。作息算正常，十二点左右睡，早上八点前起。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢历史、科幻、摄影、火锅。工作稳定，计划在这边住一到两年。', '希望室友爱干净，公共区域用完能及时收拾。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '历史,科幻,摄影,火锅', NULL, '已通过', NULL, '2026-10-03 14:34:17', '是', '2026-10-03 14:23:45', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (707, 708, '行洲', '男', '1997-09-17 00:00:00', 4000, '整洁', '咖啡师', '2年以上', 16, '正常作息', '无', '不吸烟', '我在闵行这边上班，做咖啡师。作息算正常，十二点左右睡，早上八点前起。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢撸狗、棋类、科幻、火锅。准备长住，至少两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '撸狗,棋类,科幻,火锅', NULL, '已通过', NULL, '2026-10-02 11:35:33', '是', '2026-10-02 11:13:59', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (708, 709, '星涵', '男', '1984-01-08 00:00:00', 3300, '整洁', '民警', '1-2年', 16, '正常作息', '无', '不吸烟', '目前在闵行做民警，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢密室逃脱、房车旅行、探店。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '密室逃脱,房车旅行,探店', NULL, '已通过', NULL, '2026-10-03 02:45:00', '是', '2026-10-03 02:40:10', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (709, 710, '程铭', '男', '1991-07-07 00:00:00', 1800, '一般', '编辑', '1-2年', 16, '正常作息', '无', '偶尔', '做编辑的，公司离紫竹店不远。一般十二点前睡觉，周末会稍微睡个懒觉。卫生习惯一般，垃圾每天倒，房间一周收拾一次。偶尔会抽烟，但只在楼下抽，不在屋里。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢咖啡、哲学、宠物摄影、游泳。工作稳定，计划在这边住一到两年。', '对动物毛发过敏，不能接受室友养宠物。如果能偶尔一起做饭就更好了。', '咖啡,哲学,宠物摄影,游泳,舞蹈,滑雪', NULL, '已通过', NULL, '2026-10-03 06:34:10', '是', '2026-10-03 06:17:07', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (710, 711, '谭柏昭', '男', '1998-01-05 00:00:00', 4100, '整洁', '心理咨询师', '6-12个月', 16, '夜猫子', '无', '不吸烟', '做心理咨询师的，公司离紫竹店不远。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢唱歌、古镇游、游泳。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。相处简单一点，有事好商量。', '唱歌,古镇游,游泳', NULL, '已通过', NULL, '2026-10-01 05:57:54', '是', '2026-10-01 05:52:33', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (711, 712, '洲涵', '男', '1985-03-08 00:00:00', 2900, '一般', '培训讲师', '1-2年', 16, '正常作息', '无', '不吸烟', '我在闵行这边上班，做培训讲师。作息算正常，十二点左右睡，早上八点前起。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢烘焙、插画、背包客。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '烘焙,插画,背包客', NULL, '已通过', NULL, '2026-10-01 06:11:23', '是', '2026-10-01 06:03:32', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (712, 713, '亦舟', '男', '2000-10-05 00:00:00', 4100, '整洁', '电商运营', '1-2年', 16, '正常作息', '有', '经常', '目前在闵行做电商运营，想找个近一点的地方住。一般十二点前睡觉，周末会稍微睡个懒觉。东西习惯分类收纳，厨房用完当天就擦干净。养了一只猫，很安静，猫砂每天清。有抽烟的习惯，会尽量去阳台或楼下抽。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢杂志、烘焙、宠物公益、骑行。工作稳定，计划在这边住一到两年。', '希望室友能接受我养的小宠物。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '杂志,烘焙,宠物公益,骑行,茶道,出境游', NULL, '已通过', NULL, '2026-10-01 13:28:34', '是', '2026-10-01 13:15:47', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (713, 714, '莹禾', '女', '1993-03-11 00:00:00', 4000, '随意', '审计师', '6-12个月', 16, '夜猫子', '无', '不吸烟', '目前在闵行做审计师，想找个近一点的地方住。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。对整洁要求不高，东西放得有点随意，不过不会影响别人。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢宠物公益、瑜伽、手工、主机游戏。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '宠物公益,瑜伽,手工,主机游戏,乐器,撸猫', NULL, '已通过', NULL, '2026-10-03 08:42:51', '是', '2026-10-03 08:30:45', '2026-10-03 21:10:17');
