INSERT INTO `member_profile` VALUES (715, 716, '慕芸', '女', '2001-10-26 00:00:00', 4000, '整洁', '人力资源专员', '3个月以下', 16, '早睡早起', '有', '不吸烟', '做人力资源专员的，公司离紫竹店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。东西习惯分类收纳，厨房用完当天就擦干净。养了一只猫，很安静，猫砂每天清。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢插画、烧烤、骑行、养鱼。最近是过渡期，先住两三个月看看。', '希望室友作息规律，晚上十一点后尽量安静。希望室友能接受我养的小宠物。如果能偶尔一起做饭就更好了。', '插画,烧烤,骑行,养鱼,杂志', NULL, '已通过', NULL, '2026-10-03 17:07:18', '是', '2026-10-03 16:50:30', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (716, 717, '奕嘉', '男', '1989-11-22 00:00:00', 2400, '一般', '护士', '1-2年', 16, '早睡早起', '无', '不吸烟', '我在闵行这边上班，做护士。每天七点前起床晨跑，晚上很少熬夜。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢养鸟、听播客、桌游、诗集。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '养鸟,听播客,桌游,诗集', NULL, '已通过', NULL, '2026-10-02 14:17:48', '是', '2026-10-02 14:15:19', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (717, 718, '韵景', '女', '2003-05-19 00:00:00', 1800, '一般', '博物馆讲解员', '6-12个月', 16, '正常作息', '无', '不吸烟', '做博物馆讲解员的，公司离紫竹店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢自驾游、追剧、拼图、看纪录片。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '自驾游,追剧,拼图,看纪录片,养鸟', NULL, '已通过', NULL, '2026-10-02 06:00:31', '是', '2026-10-02 05:55:17', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (718, 719, '越星', '男', '1997-01-04 00:00:00', 1900, '随意', '后端工程师', '2年以上', 16, '正常作息', '无', '不吸烟', '做后端工程师的，公司离紫竹店不远。作息算正常，十二点左右睡，早上八点前起。对整洁要求不高，东西放得有点随意，不过不会影响别人。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢传记、海岛游、乒乓球、羽毛球。准备长住，至少两年。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '传记,海岛游,乒乓球,羽毛球,哲学,健身', NULL, '已通过', NULL, '2026-10-02 17:07:50', '是', '2026-10-02 17:05:34', '2026-10-03 21:10:17');
