INSERT INTO `member_profile` VALUES (739, 740, '铭云', '男', '2003-08-14 00:00:00', 4200, '一般', '律师', '3-6个月', 17, '夜猫子', '无', '偶尔', '目前在普陀做律师，想找个近一点的地方住。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。卫生习惯一般，垃圾每天倒，房间一周收拾一次。偶尔会抽烟，但只在楼下抽，不在屋里。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢城市漫步、看动漫、书法、经济学。项目驻场半年左右，计划租三到六个月。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。相处简单一点，有事好商量。', '城市漫步,看动漫,书法,经济学,瑜伽', NULL, '已通过', NULL, '2026-10-02 17:14:40', '是', '2026-10-02 17:08:17', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (740, 741, '徐若楠', '女', '1990-05-08 00:00:00', 3500, '一般', '翻译', '6-12个月', 17, '正常作息', '无', '不吸烟', '做翻译的，公司离长风店不远。作息算正常，十二点左右睡，早上八点前起。公共区域愿意排值日轮流打扫。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢徒步、乐器、养鸟。打算先签一年以内。', '相处简单一点，有事好商量。', '徒步,乐器,养鸟', NULL, '已通过', NULL, '2026-10-02 08:41:16', '是', '2026-10-02 08:24:10', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (741, 742, '景涵', '男', '1987-11-02 00:00:00', 3900, '整洁', '康复治疗师', '1-2年', 17, '正常作息', '无', '不吸烟', '做康复治疗师的，平时喜欢养鸟、古镇游，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '养鸟,古镇游,看纪录片,房车旅行,听音乐会,追剧', NULL, '已通过', NULL, '2026-10-01 17:37:54', '是', '2026-10-01 17:19:13', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (742, 743, '慕嘉', '女', '1992-11-21 00:00:00', 3800, '整洁', '厨师', '6-12个月', 17, '正常作息', '有', '不吸烟', '做厨师的，平时喜欢心理学、甜品，人比较好相处。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望室友能接受我养的小宠物。如果能偶尔一起做饭就更好了。', '心理学,甜品,养鸟,乒乓球,游泳,历史', NULL, '已通过', NULL, '2026-10-02 21:37:37', '是', '2026-10-02 21:27:11', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (743, 744, '宁彤', '女', '1994-12-13 00:00:00', 3900, '整洁', '土木工程师', '1-2年', 17, '早睡早起', '无', '不吸烟', '我在普陀这边上班，做土木工程师。作息很规律，一般十点半前睡，早上六点多就起了。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看纪录片、茶道、传记。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。如果能偶尔一起做饭就更好了。', '看纪录片,茶道,传记', NULL, '已通过', NULL, '2026-10-02 01:16:58', '是', '2026-10-02 00:59:18', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (744, 745, '墨以', '女', '1988-05-26 00:00:00', 3100, '整洁', '房产经纪', '6-12个月', 17, '正常作息', '无', '不吸烟', '目前在普陀做房产经纪，想找个近一点的地方住。一般十二点前睡觉，周末会稍微睡个懒觉。东西习惯分类收纳，厨房用完当天就擦干净。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢桌游、古镇游、剧本杀、探店。打算先签一年以内。', '希望室友爱干净，公共区域用完能及时收拾。相处简单一点，有事好商量。', '桌游,古镇游,剧本杀,探店', NULL, '已通过', NULL, '2026-10-02 20:30:13', '是', '2026-10-02 20:06:26', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (745, 746, '恒然', '男', '2000-12-06 00:00:00', 3600, '整洁', '物流主管', '1-2年', 17, '正常作息', '无', '不吸烟', '做物流主管的，公司离长风店不远。一般十二点前睡觉，周末会稍微睡个懒觉。东西习惯分类收纳，厨房用完当天就擦干净。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢下厨、小说、密室逃脱、看电影。工作稳定，计划在这边住一到两年。', '希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '下厨,小说,密室逃脱,看电影,主机游戏,篮球', NULL, '已通过', NULL, '2026-10-01 23:53:41', '是', '2026-10-01 23:32:10', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (746, 747, '芊婉', '女', '1991-08-24 00:00:00', 3000, '洁癖', '品牌策划', '3-6个月', 17, '早睡早起', '无', '不吸烟', '目前在普陀做品牌策划，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢经济学、撸猫、杂志、宠物公益。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '经济学,撸猫,杂志,宠物公益,看话剧,听音乐', NULL, '已通过', NULL, '2026-10-01 19:04:29', '是', '2026-10-01 18:57:51', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (747, 748, '安墨', '女', '1994-01-25 00:00:00', 3800, '一般', '物流主管', '6-12个月', 17, '正常作息', '无', '不吸烟', '做物流主管的，公司离长风店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。公共区域愿意排值日轮流打扫。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢主机游戏、火锅、看展。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。相处简单一点，有事好商量。', '主机游戏,火锅,看展', NULL, '已通过', NULL, '2026-10-01 11:05:41', '是', '2026-10-01 10:52:23', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (748, 749, '奕林', '男', '2001-12-01 00:00:00', 3900, '随意', '消防员', '1-2年', 17, '正常作息', '有', '偶尔', '做消防员的，公司离长风店不远。一般十二点前睡觉，周末会稍微睡个懒觉。自己房间不算特别整齐，但公共区域用完会收拾。养了一只猫，很安静，猫砂每天清。偶尔会抽烟，但只在楼下抽，不在屋里。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢散文、端游、烘焙、跑步。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友能接受我养的小宠物。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '散文,端游,烘焙,跑步,小说,撸狗', NULL, '已通过', NULL, '2026-10-01 07:11:43', '是', '2026-10-01 06:49:21', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (749, 750, '屿星', '男', '1990-10-23 00:00:00', 3700, '一般', '会计', '1-2年', 17, '早睡早起', '无', '不吸烟', '做会计的，公司离长风店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢火锅、宠物公益、科幻。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '火锅,宠物公益,科幻', NULL, '已通过', NULL, '2026-10-02 10:56:11', '是', '2026-10-02 10:52:37', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (750, 751, '任葵雨', '女', '1997-05-03 00:00:00', 3600, '一般', '销售经理', '6-12个月', 17, '夜猫子', '无', '不吸烟', '做销售经理的，公司离长风店不远。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。公共区域愿意排值日轮流打扫。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢爬宠、瑜伽、听播客、城市漫步。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '爬宠,瑜伽,听播客,城市漫步,剧本杀', NULL, '已通过', NULL, '2026-10-03 06:06:16', '是', '2026-10-03 05:39:22', '2026-10-03 21:10:17');
