INSERT INTO `member_profile` VALUES (773, 774, '铭奕', '男', '1983-11-22 00:00:00', 2400, '整洁', '行政专员', '1-2年', 18, '正常作息', '无', '不吸烟', '目前在普陀做行政专员，想找个近一点的地方住。工作日朝九晚六，晚上偶尔追剧到十二点左右。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢传记、品酒、听音乐会、骑行。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '传记,品酒,听音乐会,骑行,咖啡', NULL, '已通过', NULL, '2026-10-02 21:19:53', '是', '2026-10-02 21:18:12', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (774, 775, '思晚', '女', '1989-04-02 00:00:00', 3200, '随意', '土木工程师', '3个月以下', 18, '早睡早起', '无', '不吸烟', '目前在普陀做土木工程师，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。对整洁要求不高，东西放得有点随意，不过不会影响别人。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢追剧、小说、插画。最近是过渡期，先住两三个月看看。', '希望室友作息规律，晚上十一点后尽量安静。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '追剧,小说,插画', NULL, '已通过', NULL, '2026-10-01 11:31:49', '是', '2026-10-01 11:30:44', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (775, 776, '以宁', '女', '2000-09-02 00:00:00', 4600, '整洁', '快递员', '6-12个月', 18, '正常作息', '无', '不吸烟', '做快递员的，公司离真如店不远。作息算正常，十二点左右睡，早上八点前起。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢乐器、绘画、插画、棋类。打算先签一年以内。', '卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '乐器,绘画,插画,棋类,火锅', NULL, '已通过', NULL, '2026-10-01 10:27:08', '是', '2026-10-01 09:59:55', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (776, 777, '树亦', '男', '1996-12-14 00:00:00', 4900, '一般', '体育教练', '2年以上', 18, '早睡早起', '无', '不吸烟', '做体育教练的，公司离真如店不远。每天七点前起床晨跑，晚上很少熬夜。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢桌游、城市漫步、剧本杀、电竞。准备长住，至少两年。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '桌游,城市漫步,剧本杀,电竞,心理学,书法', NULL, '已通过', NULL, '2026-10-02 08:12:33', '是', '2026-10-02 07:48:05', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (777, 778, '然舟', '男', '1998-09-30 00:00:00', 4400, '一般', '幼儿园教师', '1-2年', 18, '正常作息', '无', '不吸烟', '做幼儿园教师的，公司离真如店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢历史、桌游、小说、哲学。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '历史,桌游,小说,哲学,密室逃脱,科幻', NULL, '已通过', NULL, '2026-10-03 04:48:03', '是', '2026-10-03 04:28:38', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (778, 779, '铭阳', '男', '1991-10-19 00:00:00', 3200, '一般', '房产经纪', '6-12个月', 18, '早睡早起', '有', '不吸烟', '我在普陀这边上班，做房产经纪。作息很规律，一般十点半前睡，早上六点多就起了。公共区域愿意排值日轮流打扫。养了一只小狗，打过疫苗，每天早晚各遛一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢电竞、品酒、杂志。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友能接受我养的小宠物。能互相尊重彼此的空间就好。', '电竞,品酒,杂志', NULL, '已通过', NULL, '2026-10-03 12:03:08', '是', '2026-10-03 11:39:15', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (779, 780, '禾芊', '女', '1992-05-18 00:00:00', 3500, '随意', '培训讲师', '6-12个月', 18, '正常作息', '无', '不吸烟', '做培训讲师的，公司离真如店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。对整洁要求不高，东西放得有点随意，不过不会影响别人。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢羽毛球、端游、咖啡、听相声。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '羽毛球,端游,咖啡,听相声,绘画', NULL, '待审核', NULL, NULL, '是', '2026-10-02 19:19:19', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (780, 781, '孟云泽', '男', '1985-02-06 00:00:00', 3400, '一般', '网约车司机', '1-2年', 18, '正常作息', '无', '不吸烟', '我在普陀这边上班，做网约车司机。作息算正常，十二点左右睡，早上八点前起。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢哲学、撸狗、看综艺、宠物公益。工作稳定，计划在这边住一到两年。', '卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。', '哲学,撸狗,看综艺,宠物公益,爬宠,茶道', NULL, '已通过', NULL, '2026-10-01 15:38:22', '是', '2026-10-01 15:14:52', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (781, 782, '树时', '男', '2001-10-10 00:00:00', 2900, '一般', '测绘工程师', '6-12个月', 18, '早睡早起', '无', '不吸烟', '做测绘工程师的，公司离真如店不远。每天七点前起床晨跑，晚上很少熬夜。公共区域愿意排值日轮流打扫。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢宠物公益、舞蹈、乒乓球。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '宠物公益,舞蹈,乒乓球', NULL, '已通过', NULL, '2026-10-01 03:01:18', '是', '2026-10-01 02:56:44', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (782, 783, '汐念', '女', '2003-04-18 00:00:00', 2700, '整洁', '界面设计师', '1-2年', 18, '正常作息', '无', '不吸烟', '我在普陀这边上班，做界面设计师。一般十二点前睡觉，周末会稍微睡个懒觉。比较爱干净，公共区域用完马上收拾。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢海岛游、背包客、舞蹈、追剧。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '海岛游,背包客,舞蹈,追剧', NULL, '已通过', NULL, '2026-10-02 03:51:37', '是', '2026-10-02 03:43:22', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (783, 784, '川家', '男', '2001-02-01 00:00:00', 2400, '一般', '幼儿园教师', '3个月以下', 18, '正常作息', '有', '不吸烟', '做幼儿园教师的，公司离真如店不远。作息算正常，十二点左右睡，早上八点前起。公共区域愿意排值日轮流打扫。养了一只猫，很安静，猫砂每天清。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢养狗、手工、看动漫、养猫。最近是过渡期，先住两三个月看看。', '卫生方面大家互相体谅就好。希望室友能接受我养的小宠物。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '养狗,手工,看动漫,养猫', NULL, '已通过', NULL, '2026-10-02 15:46:54', '是', '2026-10-02 15:17:35', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (784, 785, '时钧', '男', '1996-04-24 00:00:00', 3500, '一般', '个体经营', '1-2年', 18, '正常作息', '无', '不吸烟', '我在普陀这边上班，做个体经营。工作日朝九晚六，晚上偶尔追剧到十二点左右。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢桌游、爬宠、卡牌、看话剧。工作稳定，计划在这边住一到两年。', '卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '桌游,爬宠,卡牌,看话剧,骑行', NULL, '已通过', NULL, '2026-10-02 06:34:55', '是', '2026-10-02 06:09:23', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (785, 786, '墨行', '男', '1981-09-29 00:00:00', 5900, '随意', '法务专员', '6-12个月', 18, '夜猫子', '无', '经常', '目前在普陀做法务专员，想找个近一点的地方住。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。自己房间不算特别整齐，但公共区域用完会收拾。有抽烟的习惯，会尽量去阳台或楼下抽。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢插画、撸猫、听音乐、瑜伽。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '插画,撸猫,听音乐,瑜伽,养鱼,听播客', NULL, '已通过', NULL, '2026-10-02 16:48:36', '是', '2026-10-02 16:27:08', '2026-10-03 21:10:17');
