INSERT INTO `member_profile` VALUES (790, 791, '庄瑾楠', '女', '1996-04-18 00:00:00', 4000, '整洁', '物流主管', '6-12个月', 18, '正常作息', '无', '不吸烟', '做物流主管的，平时喜欢房车旅行、火锅，人比较好相处。', '卫生方面大家互相体谅就好。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '房车旅行,火锅,科幻', NULL, '已通过', NULL, '2026-10-01 23:50:44', '是', '2026-10-01 23:21:58', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (791, 792, '葵若', '女', '1994-01-21 00:00:00', 3400, '一般', '事业单位职员', '6-12个月', 18, '正常作息', '无', '不吸烟', '目前在普陀做事业单位职员，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢茶道、养猫、传记。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '茶道,养猫,传记', NULL, '已通过', NULL, '2026-10-01 19:05:22', '是', '2026-10-01 18:57:32', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (792, 793, '时昭', '男', '2003-09-30 00:00:00', 3100, '一般', '编辑', '1-2年', 18, '正常作息', '有', '不吸烟', '做编辑的，公司离真如店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。公共区域愿意排值日轮流打扫。养了一只小狗，打过疫苗，每天早晚各遛一次。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢出境游、剧本杀、宠物公益、历史。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友能接受我养的小宠物。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '出境游,剧本杀,宠物公益,历史,乒乓球,古镇游', NULL, '已通过', NULL, '2026-10-02 08:14:54', '是', '2026-10-02 07:56:53', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (793, 794, '楚之', '女', '1995-02-15 00:00:00', 4900, '整洁', '快递员', '2年以上', 18, '夜猫子', '无', '不吸烟', '做快递员的，公司离真如店不远。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢摄影旅行、烧烤、唱歌、科幻。准备长住，至少两年。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '摄影旅行,烧烤,唱歌,科幻,端游', NULL, '已通过', NULL, '2026-10-01 15:36:49', '是', '2026-10-01 15:14:59', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (794, 795, '以书', '女', '1986-08-31 00:00:00', 3100, '整洁', '幼儿园教师', '6-12个月', 18, '夜猫子', '无', '不吸烟', '做幼儿园教师的，公司离真如店不远。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢散文、古镇游、咖啡。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '散文,古镇游,咖啡', NULL, '已通过', NULL, '2026-10-01 04:12:33', '是', '2026-10-01 04:10:42', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (795, 796, '书莹', '女', '1991-05-28 00:00:00', 4800, '整洁', '机械工程师', '3-6个月', 18, '早睡早起', '无', '不吸烟', '做机械工程师的，公司离真如店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢爬山、养鱼、露营、舞蹈。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。如果能偶尔一起做饭就更好了。', '爬山,养鱼,露营,舞蹈,看动漫,密室逃脱', NULL, '已通过', NULL, '2026-10-03 05:04:26', '否', '2026-10-03 04:39:22', '2026-10-03 21:10:17');
