INSERT INTO `member_profile` VALUES (806, 807, '婉薇', '女', '1984-01-21 00:00:00', 2700, '随意', '翻译', '1-2年', 18, '夜猫子', '无', '不吸烟', '我在普陀这边上班，做翻译。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。对整洁要求不高，东西放得有点随意，不过不会影响别人。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢乒乓球、烘焙、养仓鼠、游泳。工作稳定，计划在这边住一到两年。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '乒乓球,烘焙,养仓鼠,游泳,养狗,羽毛球', NULL, '已通过', NULL, '2026-10-01 20:29:32', '是', '2026-10-01 20:19:40', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (807, 808, '煜柏', '男', '1987-05-21 00:00:00', 3200, '洁癖', '审计师', '2年以上', 18, '正常作息', '有', '不吸烟', '做审计师的，平时喜欢诗集、出境游，人比较好相处。', '卫生方面大家互相体谅就好。希望室友能接受我养的小宠物。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '诗集,出境游,棋类,养狗,房车旅行,骑行', NULL, '已通过', NULL, '2026-10-01 00:41:09', '是', '2026-10-01 00:15:40', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (808, 809, '汐南', '女', '1987-01-04 00:00:00', 3900, '一般', '录音师', '1-2年', 18, '正常作息', '无', '不吸烟', '做录音师的，公司离真如店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢听音乐、摄影、健身。工作稳定，计划在这边住一到两年。', '对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '听音乐,摄影,健身', NULL, '已通过', NULL, '2026-10-03 02:39:13', '是', '2026-10-03 02:23:48', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (809, 810, '谦时', '男', '2001-05-25 00:00:00', 4100, '洁癖', '摄影师', '2年以上', 18, '夜猫子', '无', '不吸烟', '我在普陀这边上班，做摄影师。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。对卫生要求比较高，每周会给公共区域做一次深度清洁。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢摄影、杂志、滑雪。准备长住，至少两年。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。能互相尊重彼此的空间就好。', '摄影,杂志,滑雪', NULL, '已通过', NULL, '2026-10-02 09:10:32', '是', '2026-10-02 09:04:28', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (810, 811, '范南沐', '女', '1985-04-04 00:00:00', 3700, '一般', '测试工程师', '1-2年', 18, '早睡早起', '无', '不吸烟', '目前在普陀做测试工程师，想找个近一点的地方住。作息很规律，一般十点半前睡，早上六点多就起了。公共区域愿意排值日轮流打扫。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢听音乐会、电竞、听播客、养仓鼠。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '听音乐会,电竞,听播客,养仓鼠', NULL, '已通过', NULL, '2026-10-02 20:42:22', '是', '2026-10-02 20:40:30', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (811, 812, '之婉', '女', '1999-06-07 00:00:00', 5400, '整洁', '摄影师', '3个月以下', 19, '早睡早起', '无', '不吸烟', '做摄影师的，公司离桃浦店不远。每天七点前起床晨跑，晚上很少熬夜。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢听相声、摄影旅行、手游、书法。最近是过渡期，先住两三个月看看。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '听相声,摄影旅行,手游,书法', NULL, '已通过', NULL, '2026-10-01 02:09:08', '是', '2026-10-01 01:42:55', '2026-10-03 21:10:17');
