INSERT INTO `member_profile` VALUES (822, 823, '锐景', '男', '1999-04-15 00:00:00', 3100, '整洁', '土木工程师', '2年以上', 19, '夜猫子', '有', '不吸烟', '做土木工程师的，公司离桃浦店不远。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。比较爱干净，公共区域用完马上收拾。养了一只小狗，打过疫苗，每天早晚各遛一次。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢自驾游、养鸟、篮球、品酒。准备长住，至少两年。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。希望室友能接受我养的小宠物。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '自驾游,养鸟,篮球,品酒,出境游,杂志', NULL, '已通过', NULL, '2026-10-01 10:11:24', '是', '2026-10-01 10:06:51', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (823, 824, '泽言', '男', '1988-02-22 00:00:00', 4000, '一般', '药剂师', '6-12个月', 19, '夜猫子', '无', '不吸烟', '做药剂师的，公司离桃浦店不远。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢滑雪、徒步、密室逃脱。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '滑雪,徒步,密室逃脱', NULL, '已通过', NULL, '2026-10-01 13:46:34', '是', '2026-10-01 13:21:35', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (824, 825, '禾禾', '女', '1997-09-14 00:00:00', 4200, '整洁', '网约车司机', '3个月以下', 19, '夜猫子', '无', '不吸烟', '做网约车司机的，公司离桃浦店不远。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看展、看话剧、历史、密室逃脱。最近是过渡期，先住两三个月看看。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '看展,看话剧,历史,密室逃脱,徒步', NULL, '待审核', NULL, NULL, '是', '2026-10-02 17:43:41', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (825, 826, '语婉', '女', '1992-02-27 00:00:00', 2600, '一般', '社区工作者', '1-2年', 19, '正常作息', '无', '不吸烟', '做社区工作者的，平时喜欢日料、烘焙，人比较好相处。', '最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '日料,烘焙,火锅,爬山,露营,端游', NULL, '已通过', NULL, '2026-10-02 11:33:00', '是', '2026-10-02 11:08:32', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (826, 827, '叙家', '男', '1994-06-13 00:00:00', 3200, '洁癖', '西点师', '3-6个月', 19, '夜猫子', '无', '不吸烟', '做西点师的，平时喜欢历史、看电影，人比较好相处。', '我睡得晚，希望室友对作息不要太敏感。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '历史,看电影,烘焙,追剧,撸猫,游泳', NULL, '已通过', NULL, '2026-10-02 20:36:11', '是', '2026-10-02 20:23:50', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (827, 828, '云雨', '女', '1995-03-31 00:00:00', 3700, '一般', '市场专员', '1-2年', 19, '正常作息', '无', '不吸烟', '做市场专员的，公司离桃浦店不远。作息算正常，十二点左右睡，早上八点前起。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢看电影、城市漫步、烧烤、品酒。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '看电影,城市漫步,烧烤,品酒,传记,撸狗', NULL, '已通过', NULL, '2026-10-01 09:25:19', '是', '2026-10-01 09:20:11', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (828, 829, '怡涵', '女', '1988-08-20 00:00:00', 4300, '整洁', '编辑', '6-12个月', 19, '夜猫子', '无', '不吸烟', '我在普陀这边上班，做编辑。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢火锅、舞蹈、卡牌、下厨。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '火锅,舞蹈,卡牌,下厨', NULL, '已通过', NULL, '2026-10-02 05:30:09', '是', '2026-10-02 05:07:14', '2026-10-03 21:10:17');
