INSERT INTO `member_profile` VALUES (830, 831, '高明屿', '男', '1993-05-18 00:00:00', 4700, '整洁', '健身教练', '2年以上', 19, '正常作息', '无', '不吸烟', '做健身教练的，公司离桃浦店不远。一般十二点前睡觉，周末会稍微睡个懒觉。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢桌游、甜品、插画、游泳。准备长住，至少两年。', '希望室友爱干净，公共区域用完能及时收拾。能互相尊重彼此的空间就好。', '桌游,甜品,插画,游泳,房车旅行,听音乐', NULL, '已通过', NULL, '2026-10-02 12:54:22', '是', '2026-10-02 12:53:24', '2026-10-03 21:10:17');
