INSERT INTO `member_profile` VALUES (872, 873, '嘉砚', '男', '1993-04-17 00:00:00', 3200, '整洁', '瑜伽教练', '6-12个月', 20, '早睡早起', '无', '不吸烟', '做瑜伽教练的，公司离中山北路店不远。我习惯早睡早起，晚上十一点之后基本就不出声了。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看电影、手游、密室逃脱、心理学。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。', '看电影,手游,密室逃脱,心理学,听播客,烘焙', NULL, '已通过', NULL, '2026-10-01 16:17:00', '是', '2026-10-01 15:51:44', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (873, 874, '韵月', '女', '2000-08-22 00:00:00', 3500, '整洁', '律师', '6-12个月', 20, '正常作息', '无', '不吸烟', '做律师的，公司离中山北路店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢科幻、养狗、剧本杀。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '科幻,养狗,剧本杀', NULL, '已通过', NULL, '2026-10-03 00:15:16', '是', '2026-10-03 00:04:02', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (874, 875, '屿越', '男', '2003-01-07 00:00:00', 4500, '一般', '记者', '6-12个月', 20, '正常作息', '无', '不吸烟', '我在普陀这边上班，做记者。工作日朝九晚六，晚上偶尔追剧到十二点左右。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢出境游、茶道、桌游、插画。打算先签一年以内。', '对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。', '出境游,茶道,桌游,插画,宠物公益', NULL, '待审核', NULL, NULL, '是', '2026-10-01 18:15:54', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (875, 876, '宇家', '男', '1999-12-02 00:00:00', 2700, '洁癖', '个体经营', '3-6个月', 20, '早睡早起', '无', '不吸烟', '目前在普陀做个体经营，想找个近一点的地方住。每天七点前起床晨跑，晚上很少熬夜。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢城市漫步、撸猫、密室逃脱、诗集。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。能互相尊重彼此的空间就好。', '城市漫步,撸猫,密室逃脱,诗集,棋类', NULL, '已通过', NULL, '2026-10-01 11:25:46', '是', '2026-10-01 11:04:35', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (876, 877, '岚若', '女', '2004-06-17 00:00:00', 3500, '整洁', '心理咨询师', '6-12个月', 20, '正常作息', '无', '不吸烟', '做心理咨询师的，公司离中山北路店不远。作息算正常，十二点左右睡，早上八点前起。比较爱干净，公共区域用完马上收拾。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢徒步、宠物公益、烘焙、火锅。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '徒步,宠物公益,烘焙,火锅,游泳,经济学', NULL, '已通过', NULL, '2026-10-02 00:36:41', '是', '2026-10-02 00:22:16', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (877, 878, '家岩', '男', '2003-12-25 00:00:00', 3400, '洁癖', '餐饮店主', '3-6个月', 20, '早睡早起', '无', '经常', '目前在普陀做餐饮店主，想找个近一点的地方住。我习惯早睡早起，晚上十一点之后基本就不出声了。有点洁癖，卫生间和厨房希望每次用完都擦干。有抽烟的习惯，会尽量去阳台或楼下抽。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢养仓鼠、追剧、日料、手工。项目驻场半年左右，计划租三到六个月。', '希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。对动物毛发过敏，不能接受室友养宠物。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '养仓鼠,追剧,日料,手工', NULL, '待审核', NULL, NULL, '是', '2026-10-03 01:52:41', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (878, 879, '尘韵', '女', '1981-10-05 00:00:00', 4800, '整洁', '培训讲师', '6-12个月', 20, '夜猫子', '有', '偶尔', '我在普陀这边上班，做培训讲师。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。比较爱干净，公共区域用完马上收拾。养了一只猫，很安静，猫砂每天清。偶尔会抽烟，但只在楼下抽，不在屋里。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢卡牌、品酒、爬山。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。希望室友能接受我养的小宠物。希望能长期稳定住，不要频繁换人。如果能偶尔一起做饭就更好了。', '卡牌,品酒,爬山', NULL, '已通过', NULL, '2026-10-03 11:40:27', '是', '2026-10-03 11:33:13', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (879, 880, '屿涵', '男', '1991-11-17 00:00:00', 3100, '洁癖', '民警', '6-12个月', 20, '正常作息', '无', '不吸烟', '目前在普陀做民警，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看纪录片、绘画、舞蹈、乒乓球。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '看纪录片,绘画,舞蹈,乒乓球,书法', NULL, '已通过', NULL, '2026-10-01 17:20:08', '是', '2026-10-01 16:59:04', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (880, 881, '黄亭妍', '女', '1984-06-06 00:00:00', 5400, '一般', '平面设计师', '6-12个月', 20, '夜猫子', '无', '不吸烟', '做平面设计师的，公司离中山北路店不远。工作常常要加班，回到家一般十一二点了，第二天睡到八九点。公共区域愿意排值日轮流打扫。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢端游、咖啡、看纪录片。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。希望能长期稳定住，不要频繁换人。能互相尊重彼此的空间就好。', '端游,咖啡,看纪录片', NULL, '已通过', NULL, '2026-10-02 23:13:48', '是', '2026-10-02 23:05:48', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (881, 882, '川松', '男', '2001-09-10 00:00:00', 2800, '整洁', '餐饮店主', '3-6个月', 20, '夜猫子', '无', '经常', '做餐饮店主的，平时喜欢乐器、看话剧，人比较好相处。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。能互相尊重彼此的空间就好。', '乐器,看话剧,宠物摄影,传记,爬山', NULL, '已通过', NULL, '2026-10-02 06:22:24', '是', '2026-10-02 05:55:40', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (882, 883, '涵洲', '男', '2001-02-16 00:00:00', 5200, '整洁', '会计', '1-2年', 20, '正常作息', '无', '偶尔', '目前在普陀做会计，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。东西习惯分类收纳，厨房用完当天就擦干净。偶尔会抽烟，但只在楼下抽，不在屋里。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢咖啡、历史、羽毛球、爬宠。工作稳定，计划在这边住一到两年。', '希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。如果能偶尔一起做饭就更好了。', '咖啡,历史,羽毛球,爬宠,宠物公益,瑜伽', NULL, '已通过', NULL, '2026-10-01 16:05:16', '是', '2026-10-01 15:39:56', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (883, 884, '清知', '女', '1985-04-18 00:00:00', 3900, '一般', '餐饮店主', '6-12个月', 20, '夜猫子', '无', '不吸烟', '我在普陀这边上班，做餐饮店主。晚上精神比较好，习惯熬夜看书打游戏，会注意不吵到别人。卫生习惯一般，垃圾每天倒，房间一周收拾一次。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢乒乓球、篮球、滑雪、露营。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。最好就在同一家门店，通勤方便。相处简单一点，有事好商量。', '乒乓球,篮球,滑雪,露营,看话剧,养鱼', NULL, '已通过', NULL, '2026-10-02 16:19:48', '是', '2026-10-02 16:09:36', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (884, 885, '尘月', '女', '1996-08-11 00:00:00', 3100, '整洁', '银行柜员', '1-2年', 20, '正常作息', '无', '不吸烟', '目前在普陀做银行柜员，想找个近一点的地方住。作息算正常，十二点左右睡，早上八点前起。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢骑行、下厨、科幻、城市漫步。工作稳定，计划在这边住一到两年。', '希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。', '骑行,下厨,科幻,城市漫步,健身,小说', NULL, '已通过', NULL, '2026-10-01 23:13:03', '是', '2026-10-01 22:46:01', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (885, 886, '宇岩', '男', '1993-01-06 00:00:00', 3600, '整洁', '康复治疗师', '6-12个月', 20, '夜猫子', '无', '不吸烟', '我在普陀这边上班，做康复治疗师。我是夜猫子，经常一两点才睡，不过晚上会戴耳机、动静很小。东西习惯分类收纳，厨房用完当天就擦干净。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢历史、日料、撸狗、摄影旅行。打算先签一年以内。', '我睡得晚，希望室友对作息不要太敏感。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。相处简单一点，有事好商量。', '历史,日料,撸狗,摄影旅行', NULL, '已通过', NULL, '2026-10-02 23:27:28', '是', '2026-10-02 23:20:04', '2026-10-03 21:10:17');
INSERT INTO `member_profile` VALUES (886, 887, '月芸', '女', '1991-01-10 00:00:00', 2900, '随意', '中学教师', '6-12个月', 20, '正常作息', '无', '不吸烟', '做中学教师的，公司离中山北路店不远。工作日朝九晚六，晚上偶尔追剧到十二点左右。对整洁要求不高，东西放得有点随意，不过不会影响别人。不抽烟，也闻不惯烟味。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢看动漫、火锅、养狗。打算先签一年以内。', '希望室友作息规律，晚上十一点后尽量安静。能互相尊重彼此的空间就好。', '看动漫,火锅,养狗', NULL, '已通过', NULL, '2026-10-03 06:52:53', '是', '2026-10-03 06:24:53', '2026-10-03 21:10:17');
