INSERT INTO `tool_call_log` VALUES (147, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 889}', '{\"candidate_member_id\": 889, \"nickname\": \"之慕\", \"gender\": \"女\", \"age\": 30, \"rent_budget\": 3200, \"tidiness\": \"洁癖\", \"occupation\": \"图书管理员\", \"lease_term\": \"2年以上\", \"store\": \"中山北路店\", \"area\": \"普陀\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"偶尔\", \"self_intro\": \"做图书管理员的，平时喜欢自驾游、甜品，人比较好相处。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。如果能偶尔一起做饭就更好了。\", \"interest_tags\": [\"自驾游\", \"甜品\", \"听播客\"], \"preference\": {\"age\": {\"range\": [25, 34], \"required\": \"加分\"}, \"budget\": {\"range\": [2000, 4700], \"required\": \"必须\"}, \"tidiness\": {\"min\": null, \"required\": \"加分\"}, \"store\": {\"scope\": \"同门店\", \"required\": \"必须\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": null, \"required\": \"加分\"}, \"pet\": {\"accept\": \"接受\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 3, '2026-10-04 12:49:07');
INSERT INTO `tool_call_log` VALUES (148, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 768}', '{\"candidate_member_id\": 768, \"nickname\": \"韵心\", \"gender\": \"女\", \"age\": 26, \"rent_budget\": 3800, \"tidiness\": \"整洁\", \"occupation\": \"人力资源专员\", \"lease_term\": \"1-2年\", \"store\": \"真如店\", \"area\": \"普陀\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"做人力资源专员的，公司离真如店不远。每天七点前起床晨跑，晚上很少熬夜。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢烘焙、篮球、背包客、听相声。工作稳定，计划在这边住一到两年。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。相处简单一点，有事好商量。\", \"interest_tags\": [\"烘焙\", \"篮球\", \"背包客\", \"听相声\", \"日料\", \"陶艺\"], \"preference\": {\"age\": {\"range\": [21, 29], \"required\": \"必须\"}, \"budget\": {\"range\": [3300, 4300], \"required\": \"加分\"}, \"tidiness\": {\"min\": \"一般\", \"required\": \"加分\"}, \"store\": {\"scope\": \"同片区\", \"required\": \"必须\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": null, \"required\": \"加分\"}, \"pet\": {\"accept\": \"不接受\", \"required\": \"必须\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 2, '2026-10-04 12:49:07');
INSERT INTO `tool_call_log` VALUES (149, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 743}', '{\"candidate_member_id\": 743, \"nickname\": \"宁彤\", \"gender\": \"女\", \"age\": 31, \"rent_budget\": 3900, \"tidiness\": \"整洁\", \"occupation\": \"土木工程师\", \"lease_term\": \"1-2年\", \"store\": \"长风店\", \"area\": \"普陀\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"我在普陀这边上班，做土木工程师。作息很规律，一般十点半前睡，早上六点多就起了。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。基本点外卖，很少用厨房。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢看纪录片、茶道、传记。工作稳定，计划在这边住一到两年。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。对动物毛发过敏，不能接受室友养宠物。如果能偶尔一起做饭就更好了。\", \"interest_tags\": [\"看纪录片\", \"茶道\", \"传记\"], \"preference\": {\"age\": {\"range\": [30, 36], \"required\": \"加分\"}, \"budget\": {\"range\": [2700, 5400], \"required\": \"加分\"}, \"tidiness\": {\"min\": \"一般\", \"required\": \"必须\"}, \"store\": {\"scope\": \"同片区\", \"required\": \"加分\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": \"3-6个月\", \"required\": \"加分\"}, \"pet\": {\"accept\": \"不接受\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 3, '2026-10-04 12:49:07');
INSERT INTO `tool_call_log` VALUES (150, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 667}', '{\"candidate_member_id\": 667, \"nickname\": \"岚沐\", \"gender\": \"女\", \"age\": 28, \"rent_budget\": 3500, \"tidiness\": \"洁癖\", \"occupation\": \"博物馆讲解员\", \"lease_term\": \"6-12个月\", \"store\": \"虹桥枢纽店\", \"area\": \"闵行\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"目前在闵行做博物馆讲解员，想找个近一点的地方住。作息很规律，一般十点半前睡，早上六点多就起了。有点洁癖，卫生间和厨房希望每次用完都擦干。不吸烟不酗酒。周末喜欢自己做饭，厨房用完会收拾干净。偶尔周末会有朋友来坐坐，会提前跟室友说一声。平时喜欢烘焙、看电影、手游。打算先签一年以内。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。最好就在同一家门店，通勤方便。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。\", \"interest_tags\": [\"烘焙\", \"看电影\", \"手游\"], \"preference\": {\"age\": {\"range\": [26, 33], \"required\": \"必须\"}, \"budget\": {\"range\": [2300, 4300], \"required\": \"必须\"}, \"tidiness\": {\"min\": null, \"required\": \"加分\"}, \"store\": {\"scope\": \"同门店\", \"required\": \"必须\"}, \"schedule\": {\"accept\": [\"早睡早起\"], \"required\": \"必须\"}, \"lease\": {\"min\": null, \"required\": \"加分\"}, \"pet\": {\"accept\": \"无所谓\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 2, '2026-10-04 12:49:07');
INSERT INTO `tool_call_log` VALUES (151, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 625}', '{\"candidate_member_id\": 625, \"nickname\": \"书月\", \"gender\": \"女\", \"age\": 29, \"rent_budget\": 4000, \"tidiness\": \"整洁\", \"occupation\": \"算法工程师\", \"lease_term\": \"1-2年\", \"store\": \"七宝店\", \"area\": \"闵行\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"目前在闵行做算法工程师，想找个近一点的地方住。作息很规律，一般十点半前睡，早上六点多就起了。比较爱干净，公共区域用完马上收拾。不抽烟，也闻不惯烟味。周末喜欢自己做饭，厨房用完会收拾干净。很少带朋友回来。平时喜欢棋类、养狗、露营、听播客。工作稳定，计划在这边住一到两年。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望室友不在屋里抽烟。相处简单一点，有事好商量。\", \"interest_tags\": [\"棋类\", \"养狗\", \"露营\", \"听播客\", \"篮球\", \"杂志\"], \"preference\": {\"age\": {\"range\": [26, 34], \"required\": \"加分\"}, \"budget\": {\"range\": [2800, 5500], \"required\": \"必须\"}, \"tidiness\": {\"min\": null, \"required\": \"加分\"}, \"store\": {\"scope\": \"不限\", \"required\": \"加分\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": \"3-6个月\", \"required\": \"加分\"}, \"pet\": {\"accept\": \"无所谓\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 4, '2026-10-04 12:49:07');
INSERT INTO `tool_call_log` VALUES (152, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 546}', '{\"candidate_member_id\": 546, \"nickname\": \"嘉安\", \"gender\": \"女\", \"age\": 23, \"rent_budget\": 3400, \"tidiness\": \"整洁\", \"occupation\": \"运维工程师\", \"lease_term\": \"1-2年\", \"store\": \"莘庄店\", \"area\": \"闵行\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"做运维工程师的，公司离莘庄店不远。每天七点前起床晨跑，晚上很少熬夜。东西习惯分类收纳，厨房用完当天就擦干净。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢舞蹈、出境游、心理学、卡牌。工作稳定，计划在这边住一到两年。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。最好就在同一家门店，通勤方便。希望能长期稳定住，不要频繁换人。希望室友不在屋里抽烟。如果能偶尔一起做饭就更好了。\", \"interest_tags\": [\"舞蹈\", \"出境游\", \"心理学\", \"卡牌\"], \"preference\": {\"age\": {\"range\": [19, 29], \"required\": \"必须\"}, \"budget\": {\"range\": [2400, 4200], \"required\": \"必须\"}, \"tidiness\": {\"min\": \"整洁\", \"required\": \"加分\"}, \"store\": {\"scope\": \"同门店\", \"required\": \"加分\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": \"1-2年\", \"required\": \"加分\"}, \"pet\": {\"accept\": \"无所谓\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 5, '2026-10-04 12:49:07');
INSERT INTO `tool_call_log` VALUES (153, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 508}', '{\"candidate_member_id\": 508, \"nickname\": \"洲楚\", \"gender\": \"女\", \"age\": 27, \"rent_budget\": 3600, \"tidiness\": \"洁癖\", \"occupation\": \"博物馆讲解员\", \"lease_term\": \"6-12个月\", \"store\": \"大桥店\", \"area\": \"杨浦\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"我在杨浦这边上班，做博物馆讲解员。我习惯早睡早起，晚上十一点之后基本就不出声了。对卫生要求比较高，每周会给公共区域做一次深度清洁。不吸烟不酗酒。基本点外卖，很少用厨房。很少带朋友回来。平时喜欢看话剧、传记、羽毛球、滑雪。打算先签一年以内。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。\", \"interest_tags\": [\"看话剧\", \"传记\", \"羽毛球\", \"滑雪\", \"听播客\", \"游泳\"], \"preference\": {\"age\": {\"range\": [25, 33], \"required\": \"必须\"}, \"budget\": {\"range\": [3100, 4600], \"required\": \"加分\"}, \"tidiness\": {\"min\": null, \"required\": \"加分\"}, \"store\": {\"scope\": \"同片区\", \"required\": \"必须\"}, \"schedule\": {\"accept\": [\"早睡早起\"], \"required\": \"加分\"}, \"lease\": {\"min\": \"6-12个月\", \"required\": \"必须\"}, \"pet\": {\"accept\": \"无所谓\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 2, '2026-10-04 12:49:07');
INSERT INTO `tool_call_log` VALUES (154, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 493}', '{\"candidate_member_id\": 493, \"nickname\": \"洛筱\", \"gender\": \"女\", \"age\": 30, \"rent_budget\": 3500, \"tidiness\": \"洁癖\", \"occupation\": \"人力资源专员\", \"lease_term\": \"6-12个月\", \"store\": \"控江店\", \"area\": \"杨浦\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"目前在杨浦做人力资源专员，想找个近一点的地方住。我习惯早睡早起，晚上十一点之后基本就不出声了。有点洁癖，卫生间和厨房希望每次用完都擦干。不抽烟，也闻不惯烟味。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢传记、小说、爬宠、桌游。打算先签一年以内。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。卫生方面大家互相体谅就好。如果能偶尔一起做饭就更好了。\", \"interest_tags\": [\"传记\", \"小说\", \"爬宠\", \"桌游\", \"火锅\"], \"preference\": {\"age\": {\"range\": [28, 33], \"required\": \"加分\"}, \"budget\": {\"range\": [2500, 5000], \"required\": \"必须\"}, \"tidiness\": {\"min\": null, \"required\": \"加分\"}, \"store\": {\"scope\": \"不限\", \"required\": \"加分\"}, \"schedule\": {\"accept\": [\"早睡早起\"], \"required\": \"必须\"}, \"lease\": {\"min\": \"3-6个月\", \"required\": \"必须\"}, \"pet\": {\"accept\": \"接受\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 4, '2026-10-04 12:49:07');
INSERT INTO `tool_call_log` VALUES (155, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 433}', '{\"candidate_member_id\": 433, \"nickname\": \"墨尘\", \"gender\": \"女\", \"age\": 25, \"rent_budget\": 3500, \"tidiness\": \"洁癖\", \"occupation\": \"产品经理\", \"lease_term\": \"6-12个月\", \"store\": \"新江湾店\", \"area\": \"杨浦\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"我在杨浦这边上班，做产品经理。作息很规律，一般十点半前睡，早上六点多就起了。对卫生要求比较高，每周会给公共区域做一次深度清洁。不吸烟不酗酒。会做几个家常菜，愿意和室友一起分摊买菜。很少带朋友回来。平时喜欢摄影、手游、养仓鼠。打算先签一年以内。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。希望室友不在屋里抽烟。能互相尊重彼此的空间就好。\", \"interest_tags\": [\"摄影\", \"手游\", \"养仓鼠\"], \"preference\": {\"age\": {\"range\": [23, 32], \"required\": \"必须\"}, \"budget\": {\"range\": [2500, 4000], \"required\": \"必须\"}, \"tidiness\": {\"min\": \"一般\", \"required\": \"加分\"}, \"store\": {\"scope\": \"同片区\", \"required\": \"必须\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"必须\"}, \"lease\": {\"min\": null, \"required\": \"加分\"}, \"pet\": {\"accept\": \"接受\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 3, '2026-10-04 12:49:08');
INSERT INTO `tool_call_log` VALUES (156, 38, 'AUDITOR', 'read_candidate_preference', '{\"candidate_member_id\": 427}', '{\"candidate_member_id\": 427, \"nickname\": \"知岚\", \"gender\": \"女\", \"age\": 27, \"rent_budget\": 3700, \"tidiness\": \"整洁\", \"occupation\": \"室内设计师\", \"lease_term\": \"6-12个月\", \"store\": \"新江湾店\", \"area\": \"杨浦\", \"schedule_type\": \"早睡早起\", \"has_pet\": \"无\", \"smoking\": \"不吸烟\", \"self_intro\": \"做室内设计师的，平时喜欢电竞、看展，人比较好相处。\", \"roommate_expectation\": \"希望室友作息规律，晚上十一点后尽量安静。希望室友爱干净，公共区域用完能及时收拾。对动物毛发过敏，不能接受室友养宠物。希望能长期稳定住，不要频繁换人。相处简单一点，有事好商量。\", \"interest_tags\": [\"电竞\", \"看展\", \"桌游\"], \"preference\": {\"age\": {\"range\": [25, 35], \"required\": \"必须\"}, \"budget\": {\"range\": [2700, 5200], \"required\": \"加分\"}, \"tidiness\": {\"min\": \"整洁\", \"required\": \"必须\"}, \"store\": {\"scope\": \"不限\", \"required\": \"加分\"}, \"schedule\": {\"accept\": [\"早睡早起\", \"正常作息\"], \"required\": \"加分\"}, \"lease\": {\"min\": \"6-12个月\", \"required\": \"必须\"}, \"pet\": {\"accept\": \"不接受\", \"required\": \"加分\"}}, \"preference_missing\": null, \"portrait\": null, \"portrait_missing\": \"这位候选还没有生成画像\", \"returned\": 1}', 1, '是', NULL, 3, '2026-10-04 12:49:08');
