INSERT INTO `tool_call_log` VALUES (159, 38, 'AUDITOR', 'save_audit_result', '{\"candidate_member_id\": 743, \"audit_status\": \"否决\", \"reject_code\": \"MISMATCH_HARD\", \"reject_reason\": \"候选宁彤要求必须整洁及以上，申请方为洁癖满足；但其门店为长风店（普陀），与申请方张江店不同片区，且作息虽同为早睡早起，门店硬性条件不满足。\"}', '{\"candidate_member_id\": 743, \"audit_status\": \"否决\", \"reject_code\": \"MISMATCH_HARD\", \"returned\": 1}', 1, '是', NULL, 2, '2026-10-04 12:49:12');
