INSERT INTO `tool_call_log` VALUES (161, 38, 'AUDITOR', 'save_audit_result', '{\"candidate_member_id\": 625, \"audit_status\": \"否决\", \"reject_code\": \"MISMATCH_HARD\", \"reject_reason\": \"候选书月预算必须2800-5500元，申请方3500元满足；但书月不吸烟且闻不惯烟味，申请方偶尔吸烟，且门店为七宝店（闵行）与张江店不同片区，硬性条件不满足。\"}', '{\"candidate_member_id\": 625, \"audit_status\": \"否决\", \"reject_code\": \"MISMATCH_HARD\", \"returned\": 1}', 1, '是', NULL, 3, '2026-10-04 12:49:12');
